INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-05', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 5', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 5);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 1, 'poor', 'nghèo; kém, tồi', 'adjective', '[{"en":"His family was very poor when he was a child.","vi":"Gia đình anh ấy rất nghèo khi anh ấy còn nhỏ."},{"en":"Many poor families cannot afford to see a doctor.","vi":"Nhiều gia đình nghèo không đủ tiền đi khám bác sĩ."},{"en":"The hotel was cheap, but the food was of poor quality.","vi":"Khách sạn thì rẻ, nhưng đồ ăn chất lượng kém."}]', '[{"phrase":"poor family"},{"phrase":"poor quality"},{"phrase":"poor health"}]', NULL, '/pʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poo/poor_/poor__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 2, 'knowledge', 'kiến thức; sự hiểu biết', 'noun', '[{"en":"I only have a basic knowledge of computers.","vi":"Tôi chỉ có kiến thức cơ bản về máy tính."},{"en":"You don''t need any special knowledge to use this app.","vi":"Bạn không cần hiểu biết gì đặc biệt để dùng ứng dụng này."},{"en":"Reading every day helped him build his knowledge of English.","vi":"Đọc sách mỗi ngày đã giúp anh ấy mở rộng kiến thức tiếng Anh."}]', '[{"phrase":"basic knowledge"},{"phrase":"general knowledge"},{"phrase":"knowledge of"}]', 'không đếm được', '/ˈnɑːlɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kno/knowl/knowledge__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 3, 'laugh', 'cười (thành tiếng); cười nhạo', 'verb', '[{"en":"Everyone laughed when he told the joke.","vi":"Mọi người đều cười khi anh ấy kể câu chuyện cười."},{"en":"My little brother always makes me laugh.","vi":"Em trai tôi lúc nào cũng làm tôi bật cười."},{"en":"Please don''t laugh at me, I''m trying my best.","vi":"Làm ơn đừng cười nhạo tôi, tôi đang cố hết sức rồi."}]', '[{"phrase":"laugh at"},{"phrase":"make someone laugh"},{"phrase":"laugh out loud"}]', 'laugh at sb: cười nhạo ai', '/læf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lau/laugh/laugh__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 4, 'arm', 'cánh tay', 'noun', '[{"en":"He came to school with a broken arm.","vi":"Cậu ấy đến trường với một cánh tay bị gãy."},{"en":"The father held the sleeping baby in his arms.","vi":"Người bố bế đứa bé đang ngủ trong tay."},{"en":"The old couple walked along the beach arm in arm.","vi":"Đôi vợ chồng già khoác tay nhau đi dọc bãi biển."}]', '[{"phrase":"broken arm"},{"phrase":"arm in arm"},{"phrase":"in someone''s arms"}]', NULL, '/ɑːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arm/arm__/arm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 5, 'heart', 'tim; trái tim, tấm lòng', 'noun', '[{"en":"Eating too much salt can lead to heart disease.","vi":"Ăn quá nhiều muối có thể dẫn đến bệnh tim."},{"en":"My heart was beating fast before the exam.","vi":"Tim tôi đập nhanh trước giờ thi."},{"en":"She has a kind heart and always helps her neighbors.","vi":"Cô ấy có tấm lòng tốt và luôn giúp đỡ hàng xóm."}]', '[{"phrase":"heart disease"},{"phrase":"heart attack"},{"phrase":"kind heart"}]', NULL, '/hɑːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heart/heart__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 6, 'source', 'nguồn; nguồn gốc', 'noun', '[{"en":"Fish is a good source of protein.","vi":"Cá là một nguồn cung cấp đạm tốt."},{"en":"Tourism is the island''s main source of income.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo."},{"en":"The mechanic couldn''t find the source of the noise.","vi":"Người thợ sửa xe không tìm ra nguồn gốc của tiếng ồn."}]', '[{"phrase":"source of income"},{"phrase":"main source"},{"phrase":"energy source"}]', NULL, '/sɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/sourc/source__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 7, 'employee', 'nhân viên, người lao động', 'noun', '[{"en":"We hired three new employees this year.","vi":"Năm nay chúng tôi đã tuyển ba nhân viên mới."},{"en":"All employees must wear a name badge at work.","vi":"Tất cả nhân viên phải đeo thẻ tên khi làm việc."},{"en":"She was named employee of the month in March.","vi":"Cô ấy được bầu là nhân viên xuất sắc của tháng Ba."}]', '[{"phrase":"new employee"},{"phrase":"full-time employee"},{"phrase":"employee of the month"}]', NULL, '/ɪmˈplɔɪiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employee__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 8, 'manage', 'quản lý; xoay xở, làm được', 'verb', '[{"en":"As a team leader, she has to manage ten people.","vi":"Là trưởng nhóm, cô ấy phải quản lý mười người."},{"en":"How did you manage to finish the work so quickly?","vi":"Làm sao bạn xoay xở hoàn thành công việc nhanh vậy?"},{"en":"Don''t worry, we''ll manage without a car for a week.","vi":"Đừng lo, chúng ta sẽ xoay xở được mà không cần xe một tuần."}]', '[{"phrase":"manage to"},{"phrase":"manage a team"},{"phrase":"manage money"}]', 'manage to do sth: xoay xở làm được việc gì', '/ˈmænɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manag/manage__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 9, 'simply', 'chỉ, đơn giản là; một cách đơn giản', 'adverb', '[{"en":"I didn''t call him back simply because I forgot.","vi":"Tôi không gọi lại cho anh ấy chỉ đơn giản vì tôi quên."},{"en":"Put simply, we don''t have enough money this year.","vi":"Nói đơn giản thì năm nay chúng ta không đủ tiền."},{"en":"The teacher explained the rules simply and clearly.","vi":"Cô giáo giải thích luật một cách đơn giản và rõ ràng."}]', '[{"phrase":"simply because"},{"phrase":"put simply"},{"phrase":"quite simply"}]', NULL, '/ˈsɪmpli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simpl/simply__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 10, 'bank', 'ngân hàng; bờ (sông, hồ)', 'noun', '[{"en":"I need to go to the bank to take out some cash.","vi":"Tôi cần ra ngân hàng để rút ít tiền mặt."},{"en":"She opened a bank account when she started her first job.","vi":"Cô ấy mở tài khoản ngân hàng khi bắt đầu công việc đầu tiên."},{"en":"We had a picnic on the bank of the river.","vi":"Chúng tôi đi dã ngoại trên bờ sông."}]', '[{"phrase":"bank account"},{"phrase":"go to the bank"},{"phrase":"bank loan"}]', NULL, '/bæŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ban/bank_/bank__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 11, 'firm', 'công ty, hãng', 'noun', '[{"en":"My uncle works for a law firm in the city.","vi":"Chú tôi làm việc cho một công ty luật trong thành phố."},{"en":"She started her own design firm last year.","vi":"Năm ngoái cô ấy đã mở công ty thiết kế riêng."},{"en":"Many small firms are struggling to find workers.","vi":"Nhiều công ty nhỏ đang chật vật tìm người làm."}]', '[{"phrase":"law firm"},{"phrase":"small firm"},{"phrase":"accounting firm"}]', 'firm (adj): chắc, vững', '/fɜːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/firm_/firm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 12, 'cell', 'tế bào; điện thoại di động', 'noun', '[{"en":"Red blood cells carry oxygen around the body.","vi":"Hồng cầu vận chuyển oxy đi khắp cơ thể."},{"en":"The human body is made up of trillions of cells.","vi":"Cơ thể con người được tạo nên từ hàng nghìn tỷ tế bào."},{"en":"You can reach me on my cell after six.","vi":"Sau sáu giờ bạn có thể gọi vào di động của tôi."}]', '[{"phrase":"blood cell"},{"phrase":"brain cells"},{"phrase":"cell phone"}]', 'cell = cell phone (Mỹ); Anh: mobile phone', '/sel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cel/cell_/cell__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 13, 'article', 'bài báo, bài viết; mạo từ', 'noun', '[{"en":"I read an interesting newspaper article about sleep this morning.","vi":"Sáng nay tôi đọc một bài báo thú vị về giấc ngủ."},{"en":"She was asked to write an article for the school magazine.","vi":"Cô ấy được nhờ viết một bài cho tạp chí của trường."},{"en":"In English, \"a\" and \"the\" are articles.","vi":"Trong tiếng Anh, \"a\" và \"the\" là mạo từ."}]', '[{"phrase":"newspaper article"},{"phrase":"write an article"},{"phrase":"definite article"}]', NULL, '/ˈɑːrtɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/art/artic/article__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 14, 'fast', 'nhanh', 'adjective', '[{"en":"He''s a fast runner and often wins races at school.","vi":"Cậu ấy chạy nhanh và thường thắng các cuộc đua ở trường."},{"en":"We need a fast internet connection for online classes.","vi":"Chúng tôi cần kết nối mạng nhanh để học trực tuyến."},{"en":"Eating too much fast food is bad for your health.","vi":"Ăn quá nhiều đồ ăn nhanh không tốt cho sức khỏe."}]', '[{"phrase":"fast food"},{"phrase":"fast runner"},{"phrase":"fast internet"}]', 'fast cũng là trạng từ: run fast (chạy nhanh)', '/fæst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fas/fast_/fast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 15, 'attack', 'cuộc tấn công; cơn (bệnh)', 'noun', '[{"en":"My grandfather had a heart attack but is fine now.","vi":"Ông tôi từng bị nhồi máu cơ tim nhưng giờ đã ổn."},{"en":"The team scored after a quick attack in the second half.","vi":"Đội bóng ghi bàn sau một pha tấn công nhanh trong hiệp hai."},{"en":"Our team is strong in attack but weak in defense.","vi":"Đội chúng tôi tấn công mạnh nhưng phòng ngự yếu."}]', '[{"phrase":"heart attack"},{"phrase":"under attack"},{"phrase":"launch an attack"}]', NULL, '/əˈtæk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attack__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 16, 'foreign', '(thuộc) nước ngoài', 'adjective', '[{"en":"Learning a foreign language takes a lot of time and practice.","vi":"Học ngoại ngữ cần nhiều thời gian và luyện tập."},{"en":"The old town is always full of foreign tourists.","vi":"Phố cổ lúc nào cũng đông khách du lịch nước ngoài."},{"en":"He has worked for a foreign company for five years.","vi":"Anh ấy đã làm cho một công ty nước ngoài được năm năm."}]', '[{"phrase":"foreign language"},{"phrase":"foreign tourists"},{"phrase":"foreign country"}]', NULL, '/ˈfɔːrən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forei/foreign__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 17, 'surprise', 'sự ngạc nhiên; điều bất ngờ', 'noun', '[{"en":"We''re planning a surprise party for Mom''s birthday.","vi":"Chúng tôi đang lên kế hoạch tổ chức tiệc bất ngờ cho sinh nhật mẹ."},{"en":"To my surprise, the exam was really easy.","vi":"Tôi ngạc nhiên vì bài thi thật sự rất dễ."},{"en":"What a nice surprise to see you here!","vi":"Gặp bạn ở đây thật là bất ngờ thú vị!"}]', '[{"phrase":"surprise party"},{"phrase":"to my surprise"},{"phrase":"nice surprise"}]', NULL, '/sərˈpraɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surpr/surprise__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 18, 'feature', 'đặc điểm, nét đặc trưng; tính năng', 'noun', '[{"en":"The latest update adds a new feature for sharing photos.","vi":"Bản cập nhật mới nhất thêm một tính năng mới để chia sẻ ảnh."},{"en":"Big windows are the main feature of this house.","vi":"Những ô cửa sổ lớn là đặc điểm nổi bật của ngôi nhà này."},{"en":"One key feature of the city is its many green parks.","vi":"Một nét đặc trưng của thành phố là có nhiều công viên xanh."}]', '[{"phrase":"new feature"},{"phrase":"main feature"},{"phrase":"key feature"}]', NULL, '/ˈfiːtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fea/featu/feature__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 19, 'factor', 'yếu tố, nhân tố', 'noun', '[{"en":"Price is an important factor when you buy a car.","vi":"Giá cả là một yếu tố quan trọng khi bạn mua xe hơi."},{"en":"Stress is often a major factor in poor sleep.","vi":"Căng thẳng thường là một yếu tố chính gây ngủ kém."},{"en":"Many factors affect how well children learn at school.","vi":"Nhiều yếu tố ảnh hưởng đến việc trẻ học tốt ra sao ở trường."}]', '[{"phrase":"important factor"},{"phrase":"major factor"},{"phrase":"key factor"},{"phrase":"risk factor"}]', NULL, '/ˈfæktər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facto/factor__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 20, 'pretty', 'khá, khá là; xinh, đẹp', 'adverb', '[{"en":"The test was pretty easy, so I finished early.","vi":"Bài kiểm tra khá dễ nên tôi làm xong sớm."},{"en":"I''m pretty sure I left my keys at home.","vi":"Tôi khá chắc là mình để quên chìa khóa ở nhà."},{"en":"She looked really pretty in her new dress.","vi":"Cô ấy trông rất xinh trong chiếc váy mới."}]', '[{"phrase":"pretty sure"},{"phrase":"pretty good"},{"phrase":"pretty much"}]', 'pretty (adj): xinh, đẹp', '/ˈprɪti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prett/pretty__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 21, 'recently', 'gần đây, mới đây', 'adverb', '[{"en":"I''ve recently started going to the gym after work.","vi":"Gần đây tôi mới bắt đầu đi tập gym sau giờ làm."},{"en":"Have you seen any good movies recently?","vi":"Gần đây bạn có xem được phim nào hay không?"},{"en":"Until recently, she lived with her parents in the countryside.","vi":"Cho đến gần đây, cô ấy vẫn sống cùng bố mẹ ở quê."}]', '[{"phrase":"until recently"},{"phrase":"only recently"},{"phrase":"most recently"}]', NULL, '/ˈriːsntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recen/recently__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 22, 'affect', 'ảnh hưởng đến, tác động đến', 'verb', '[{"en":"Lack of sleep can affect your mood and memory.","vi":"Thiếu ngủ có thể ảnh hưởng đến tâm trạng và trí nhớ của bạn."},{"en":"Hundreds of flights were badly affected by the storm.","vi":"Hàng trăm chuyến bay bị ảnh hưởng nặng nề bởi cơn bão."},{"en":"How will the new rules affect students?","vi":"Các quy định mới sẽ tác động đến học sinh như thế nào?"}]', '[{"phrase":"badly affected"},{"phrase":"directly affect"},{"phrase":"seriously affect"}]', 'affect (v) ≠ effect (n)', '/əˈfekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affec/affect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 23, 'drop', 'làm rơi, đánh rơi; giảm; cho (ai) xuống xe', 'verb', '[{"en":"Be careful not to drop the plates.","vi":"Cẩn thận đừng làm rơi mấy cái đĩa nhé."},{"en":"Prices tend to drop sharply after the holidays.","vi":"Giá cả thường giảm mạnh sau kỳ nghỉ lễ."},{"en":"Can you drop me off at the station on your way?","vi":"Tiện đường bạn cho tôi xuống ở nhà ga được không?"}]', '[{"phrase":"drop sharply"},{"phrase":"drop off"},{"phrase":"drop something"}]', 'drop – dropped – dropped', '/drɑːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dro/drop_/drop__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 24, 'recent', 'gần đây, mới đây', 'adjective', '[{"en":"In recent years, more people have started working from home.","vi":"Trong những năm gần đây, nhiều người đã bắt đầu làm việc tại nhà."},{"en":"This is a recent photo of my family.","vi":"Đây là một bức ảnh chụp gia đình tôi gần đây."},{"en":"Her most recent book is about traveling alone.","vi":"Cuốn sách mới nhất của cô ấy viết về chuyện đi du lịch một mình."}]', '[{"phrase":"recent years"},{"phrase":"most recent"},{"phrase":"recent study"}]', NULL, '/ˈriːsnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recen/recent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 25, 'relate', 'liên quan; đồng cảm, thấu hiểu', 'verb', '[{"en":"Many health problems are closely related to stress.","vi":"Nhiều vấn đề sức khỏe có liên quan chặt chẽ đến căng thẳng."},{"en":"I can really relate to the main character in this movie.","vi":"Tôi thật sự đồng cảm với nhân vật chính trong bộ phim này."},{"en":"Please only ask questions that relate to today''s lesson.","vi":"Vui lòng chỉ đặt câu hỏi liên quan đến bài học hôm nay."}]', '[{"phrase":"relate to"},{"phrase":"closely related"},{"phrase":"be related to"}]', 'relate to sth/sb', '/rɪˈleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 26, 'official', 'chính thức', 'adjective', '[{"en":"The official results will be announced on Friday.","vi":"Kết quả chính thức sẽ được công bố vào thứ Sáu."},{"en":"You can buy tickets on the official website.","vi":"Bạn có thể mua vé trên trang web chính thức."},{"en":"Our country has two official languages, English and French.","vi":"Đất nước chúng tôi có hai ngôn ngữ chính thức là tiếng Anh và tiếng Pháp."}]', '[{"phrase":"official website"},{"phrase":"official language"},{"phrase":"official results"}]', 'official (n): quan chức, viên chức', '/əˈfɪʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offic/official__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 27, 'financial', '(thuộc) tài chính', 'adjective', '[{"en":"The company has had financial problems this year.","vi":"Năm nay công ty gặp khó khăn về tài chính."},{"en":"She asked a financial advisor for help with her savings.","vi":"Cô ấy nhờ một chuyên gia tư vấn tài chính giúp về khoản tiết kiệm."},{"en":"Many students need financial support to go to college.","vi":"Nhiều sinh viên cần hỗ trợ tài chính để học đại học."}]', '[{"phrase":"financial problems"},{"phrase":"financial support"},{"phrase":"financial advisor"}]', NULL, '/faɪˈnænʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finan/financial__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 28, 'miss', 'nhớ (ai, cái gì); lỡ, trễ; bỏ lỡ', 'verb', '[{"en":"I really miss my family when I''m working abroad.","vi":"Tôi rất nhớ gia đình khi đi làm ở nước ngoài."},{"en":"Hurry up or we''ll miss the bus!","vi":"Nhanh lên kẻo mình lỡ chuyến xe buýt bây giờ!"},{"en":"Don''t miss the chance to visit the old town.","vi":"Đừng bỏ lỡ cơ hội tham quan phố cổ."}]', '[{"phrase":"miss the bus"},{"phrase":"miss the chance"},{"phrase":"miss school"}]', NULL, '/mɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mis/miss_/miss__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-05', 29, 'art', 'nghệ thuật; mỹ thuật', 'noun', '[{"en":"The museum has a large collection of modern art.","vi":"Bảo tàng có một bộ sưu tập lớn về nghệ thuật hiện đại."},{"en":"My daughter loves her art class on Fridays.","vi":"Con gái tôi rất thích giờ học mỹ thuật vào thứ Sáu."},{"en":"She studied art in college and now works as a designer.","vi":"Cô ấy học mỹ thuật ở đại học và giờ làm nhà thiết kế."}]', '[{"phrase":"modern art"},{"phrase":"art class"},{"phrase":"work of art"},{"phrase":"art gallery"}]', NULL, '/ɑːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/art/art__/art__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-06', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 6', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 6);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 1, 'campaign', 'chiến dịch; cuộc vận động', 'noun', '[{"en":"The company launched a new advertising campaign last month.","vi":"Công ty đã tung ra một chiến dịch quảng cáo mới vào tháng trước."},{"en":"Our school started a campaign to reduce plastic waste.","vi":"Trường chúng tôi đã phát động một cuộc vận động giảm rác thải nhựa."},{"en":"The campaign was a big success, and sales went up quickly.","vi":"Chiến dịch rất thành công và doanh số tăng nhanh."}]', '[{"phrase":"advertising campaign"},{"phrase":"launch a campaign"},{"phrase":"marketing campaign"}]', NULL, '/kæmˈpeɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cam/campa/campaign__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 2, 'private', 'riêng tư; tư nhân; riêng', 'adjective', '[{"en":"Please don''t read my diary; it''s private.","vi":"Làm ơn đừng đọc nhật ký của tôi, đó là chuyện riêng tư."},{"en":"Her children go to a private school near the city center.","vi":"Các con cô ấy học ở một trường tư gần trung tâm thành phố."},{"en":"The hotel room had a private bathroom and a small balcony.","vi":"Phòng khách sạn có phòng tắm riêng và một ban công nhỏ."}]', '[{"phrase":"private school"},{"phrase":"private life"},{"phrase":"private company"},{"phrase":"private bathroom"}]', NULL, '/ˈpraɪvət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/priva/private__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 3, 'pause', 'tạm dừng; ngừng lại', 'verb', '[{"en":"Can you pause the movie while I get some snacks?","vi":"Bạn có thể tạm dừng phim trong lúc tôi đi lấy đồ ăn vặt không?"},{"en":"She paused for a moment before answering the question.","vi":"Cô ấy ngừng lại một lúc trước khi trả lời câu hỏi."},{"en":"We paused at the top of the hill to enjoy the view.","vi":"Chúng tôi dừng lại trên đỉnh đồi để ngắm cảnh."}]', '[{"phrase":"pause for a moment"},{"phrase":"pause the video"},{"phrase":"pause briefly"}]', NULL, '/pɔːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pau/pause/pause__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 4, 'everyone', 'mọi người; ai cũng', 'pronoun', '[{"en":"Everyone in my family loves my grandmother''s cooking.","vi":"Mọi người trong gia đình tôi đều thích món bà nấu."},{"en":"Good morning, everyone, and welcome to today''s lesson.","vi":"Chào buổi sáng mọi người, chào mừng đến với bài học hôm nay."},{"en":"Not everyone agrees with the new rules at work.","vi":"Không phải ai cũng đồng ý với các quy định mới ở chỗ làm."}]', '[{"phrase":"everyone else"},{"phrase":"everyone knows"},{"phrase":"thank everyone"}]', 'everyone đi với động từ số ít: everyone is', '/ˈevriwʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everyone__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 5, 'forget', 'quên', 'verb', '[{"en":"Don''t forget to lock the door when you leave.","vi":"Đừng quên khóa cửa khi bạn ra ngoài."},{"en":"I forgot my umbrella at the office yesterday.","vi":"Hôm qua tôi để quên ô ở văn phòng."},{"en":"Have you forgotten your sister''s birthday again?","vi":"Bạn lại quên sinh nhật em gái mình rồi à?"}]', '[{"phrase":"forget to do"},{"phrase":"forget about"},{"phrase":"never forget"},{"phrase":"completely forget"}]', 'forget – forgot – forgotten', '/fərˈɡet/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forge/forget__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 6, 'page', 'trang', 'noun', '[{"en":"Please open your books to page twenty.","vi":"Các em hãy mở sách ra trang hai mươi."},{"en":"The answers are on the last page of the book.","vi":"Đáp án nằm ở trang cuối của cuốn sách."},{"en":"I read a few pages every night before bed.","vi":"Tối nào trước khi ngủ tôi cũng đọc vài trang."}]', '[{"phrase":"front page"},{"phrase":"turn the page"},{"phrase":"next page"},{"phrase":"web page"}]', NULL, '/peɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pag/page_/page__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 7, 'worry', 'lo lắng; lo', 'verb', '[{"en":"Don''t worry, I''ll be home before dark.","vi":"Đừng lo, tôi sẽ về nhà trước khi trời tối."},{"en":"My parents always worry about my health.","vi":"Bố mẹ tôi lúc nào cũng lo lắng về sức khỏe của tôi."},{"en":"She worried that she would miss the last train.","vi":"Cô ấy lo rằng mình sẽ lỡ chuyến tàu cuối."}]', '[{"phrase":"worry about"},{"phrase":"don''t worry"},{"phrase":"worry too much"}]', 'worry about something', '/ˈwɜːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/worry/worry__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 8, 'summer', 'mùa hè', 'noun', '[{"en":"We visit my grandparents in the countryside every summer.","vi":"Mùa hè nào chúng tôi cũng về quê thăm ông bà."},{"en":"It gets very hot here in the summer.","vi":"Ở đây vào mùa hè trời rất nóng."},{"en":"Are you taking any classes this summer?","vi":"Hè này bạn có học lớp nào không?"}]', '[{"phrase":"summer holiday"},{"phrase":"last summer"},{"phrase":"summer vacation"},{"phrase":"in the summer"}]', NULL, '/ˈsʌmər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summe/summer__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 9, 'drink', 'uống; đồ uống', 'verb', '[{"en":"You should drink plenty of water when it''s hot.","vi":"Bạn nên uống nhiều nước khi trời nóng."},{"en":"He drank a cup of coffee before the meeting.","vi":"Anh ấy đã uống một tách cà phê trước cuộc họp."},{"en":"Would you like something to drink before dinner?","vi":"Bạn có muốn uống gì trước bữa tối không?"}]', '[{"phrase":"drink water"},{"phrase":"drink coffee"},{"phrase":"something to drink"}]', 'drink – drank – drunk', '/drɪŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dri/drink/drink__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 10, 'opinion', 'ý kiến; quan điểm', 'noun', '[{"en":"In my opinion, the book is better than the movie.","vi":"Theo ý kiến của tôi, cuốn sách hay hơn bộ phim."},{"en":"Everyone has a different opinion about the new park.","vi":"Mỗi người có một quan điểm khác nhau về công viên mới."},{"en":"Can I ask your opinion on this dress?","vi":"Tôi có thể hỏi ý kiến của bạn về chiếc váy này không?"}]', '[{"phrase":"in my opinion"},{"phrase":"public opinion"},{"phrase":"ask someone''s opinion"},{"phrase":"express an opinion"}]', NULL, '/əˈpɪnjən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opi/opini/opinion__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 11, 'park', 'công viên', 'noun', '[{"en":"We often take the kids to the park on Sundays.","vi":"Chúng tôi thường đưa bọn trẻ ra công viên vào Chủ nhật."},{"en":"There is a small park right behind our apartment building.","vi":"Ngay phía sau tòa chung cư của chúng tôi có một công viên nhỏ."},{"en":"My dad goes jogging in the park every morning.","vi":"Bố tôi chạy bộ trong công viên mỗi sáng."}]', '[{"phrase":"in the park"},{"phrase":"national park"},{"phrase":"theme park"},{"phrase":"walk in the park"}]', 'cũng là động từ: park a car (đỗ xe)', '/pɑːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/park_/park__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 12, 'represent', 'đại diện; tượng trưng', 'verb', '[{"en":"She was chosen to represent our school in the competition.","vi":"Cô ấy được chọn để đại diện trường chúng tôi trong cuộc thi."},{"en":"A lawyer will represent him in court.","vi":"Một luật sư sẽ đại diện cho anh ấy trước tòa."},{"en":"On this map, the blue lines represent rivers.","vi":"Trên bản đồ này, các đường màu xanh tượng trưng cho sông."}]', '[{"phrase":"represent the country"},{"phrase":"represent a client"},{"phrase":"represent the school"}]', NULL, '/ˌreprɪˈzent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repre/represent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 13, 'key', 'chìa khóa; bí quyết; phím', 'noun', '[{"en":"I can''t find my car keys anywhere.","vi":"Tôi tìm khắp nơi mà không thấy chìa khóa xe."},{"en":"Hard work is the key to success.","vi":"Chăm chỉ là bí quyết để thành công."},{"en":"Press any key on the keyboard to continue.","vi":"Nhấn phím bất kỳ trên bàn phím để tiếp tục."}]', '[{"phrase":"car keys"},{"phrase":"the key to success"},{"phrase":"press a key"},{"phrase":"lose your keys"}]', 'the key to something', '/kiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/key/key__/key__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 14, 'inside', 'bên trong; ở trong', 'preposition', '[{"en":"I left my phone inside the car.","vi":"Tôi để quên điện thoại trong xe."},{"en":"What''s inside the box you got for your birthday?","vi":"Trong chiếc hộp bạn nhận được vào sinh nhật có gì vậy?"},{"en":"It was much warmer inside the house than outside.","vi":"Bên trong nhà ấm hơn bên ngoài nhiều."}]', '[{"phrase":"inside the house"},{"phrase":"inside the box"},{"phrase":"deep inside"}]', 'inside ≠ outside', '/ˌɪnˈsaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insid/inside__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 15, 'manager', 'người quản lý; giám đốc', 'noun', '[{"en":"I''d like to speak to the manager, please.","vi":"Làm ơn cho tôi gặp người quản lý."},{"en":"She became a sales manager at twenty-eight.","vi":"Cô ấy trở thành giám đốc kinh doanh năm hai mươi tám tuổi."},{"en":"My manager lets me work from home on Fridays.","vi":"Quản lý cho tôi làm việc ở nhà vào các ngày thứ Sáu."}]', '[{"phrase":"sales manager"},{"phrase":"general manager"},{"phrase":"project manager"},{"phrase":"store manager"}]', NULL, '/ˈmænɪdʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manag/manager__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 16, 'international', 'quốc tế', 'adjective', '[{"en":"Our flight leaves from the international terminal.","vi":"Chuyến bay của chúng tôi khởi hành từ nhà ga quốc tế."},{"en":"Many international students study at this university.","vi":"Nhiều sinh viên quốc tế học tại trường đại học này."},{"en":"He works for an international company in Singapore.","vi":"Anh ấy làm việc cho một công ty quốc tế ở Singapore."}]', '[{"phrase":"international students"},{"phrase":"international airport"},{"phrase":"international company"},{"phrase":"international trade"}]', NULL, '/ˌɪntərˈnæʃnəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/international__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 17, 'contain', 'chứa; bao gồm', 'verb', '[{"en":"This drink contains a lot of sugar.","vi":"Loại đồ uống này chứa rất nhiều đường."},{"en":"The box contained old photos and letters.","vi":"Chiếc hộp chứa những bức ảnh và lá thư cũ."},{"en":"Does the final report contain any spelling mistakes?","vi":"Bản báo cáo cuối cùng có lỗi chính tả nào không?"}]', '[{"phrase":"contain information"},{"phrase":"contain sugar"},{"phrase":"contain mistakes"}]', 'không dùng ở thì tiếp diễn', '/kənˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 18, 'notice', 'nhận thấy; để ý', 'verb', '[{"en":"Did you notice that she cut her hair?","vi":"Bạn có để ý là cô ấy đã cắt tóc không?"},{"en":"I didn''t notice the mistake until I printed the letter.","vi":"Mãi đến khi in lá thư ra tôi mới nhận thấy lỗi sai."},{"en":"Nobody noticed when he left the party.","vi":"Không ai để ý khi anh ấy rời bữa tiệc."}]', '[{"phrase":"notice a change"},{"phrase":"notice a difference"},{"phrase":"suddenly notice"}]', 'cũng là danh từ: thông báo', '/ˈnəʊtɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notic/notice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 19, 'wonder', 'tự hỏi; thắc mắc', 'verb', '[{"en":"I wonder why she didn''t come to class today.","vi":"Tôi tự hỏi sao hôm nay cô ấy không đến lớp."},{"en":"We were wondering if you could help us move on Saturday.","vi":"Chúng tôi muốn hỏi liệu bạn có thể giúp chúng tôi chuyển nhà vào thứ Bảy không."},{"en":"He wondered what his old friends were doing now.","vi":"Anh ấy thắc mắc không biết giờ những người bạn cũ đang làm gì."}]', '[{"phrase":"wonder why"},{"phrase":"wonder if"},{"phrase":"I wonder whether"}]', 'I was wondering if… = cách hỏi lịch sự', '/ˈwʌndər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/won/wonde/wonder__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 20, 'nature', 'thiên nhiên; bản chất; tính cách', 'noun', '[{"en":"We love spending weekends in nature, away from the city.","vi":"Chúng tôi thích dành cuối tuần hòa mình vào thiên nhiên, tránh xa thành phố."},{"en":"It''s not in her nature to complain.","vi":"Phàn nàn không phải là tính cách của cô ấy."},{"en":"The teacher explained the nature of the problem clearly.","vi":"Giáo viên đã giải thích rõ bản chất của vấn đề."}]', '[{"phrase":"human nature"},{"phrase":"nature of the problem"},{"phrase":"in nature"},{"phrase":"love of nature"}]', 'nghĩa thiên nhiên: không đếm được', '/ˈneɪtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natur/nature__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 21, 'structure', 'cấu trúc; kết cấu; công trình', 'noun', '[{"en":"Our teacher explained the structure of a good essay.","vi":"Giáo viên đã giải thích cấu trúc của một bài luận hay."},{"en":"This sentence structure is common in spoken English.","vi":"Cấu trúc câu này rất phổ biến trong tiếng Anh nói."},{"en":"The old bridge is the tallest structure in the town.","vi":"Cây cầu cũ là công trình cao nhất trong thị trấn."}]', '[{"phrase":"sentence structure"},{"phrase":"basic structure"},{"phrase":"social structure"}]', NULL, '/ˈstrʌktʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/struc/structure__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 22, 'section', 'phần; mục; khu vực', 'noun', '[{"en":"Please read the first section of the report before the meeting.","vi":"Hãy đọc phần đầu của bản báo cáo trước cuộc họp."},{"en":"You can find cookbooks in the food section of the bookstore.","vi":"Bạn có thể tìm sách nấu ăn ở khu ẩm thực của hiệu sách."},{"en":"I usually skip the sports section of the newspaper.","vi":"Tôi thường bỏ qua mục thể thao trên báo."}]', '[{"phrase":"first section"},{"phrase":"sports section"},{"phrase":"section of the report"}]', NULL, '/ˈsekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secti/section__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 23, 'exactly', 'chính xác; đúng', 'adverb', '[{"en":"The train arrived at exactly nine o''clock.","vi":"Tàu đến đúng chín giờ."},{"en":"I don''t know exactly where he lives.","vi":"Tôi không biết chính xác anh ấy sống ở đâu."},{"en":"Your new bag looks exactly like the one my sister has.","vi":"Chiếc túi mới của bạn trông giống hệt chiếc túi của chị tôi."}]', '[{"phrase":"exactly the same"},{"phrase":"not exactly"},{"phrase":"exactly what"},{"phrase":"know exactly"}]', NULL, '/ɪɡˈzæktli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exact/exactly__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 24, 'plant', 'cây; nhà máy', 'noun', '[{"en":"Don''t forget to water the plants while I''m away.","vi":"Đừng quên tưới cây khi tôi đi vắng nhé."},{"en":"She keeps a few small plants on her office desk.","vi":"Cô ấy để vài chậu cây nhỏ trên bàn làm việc."},{"en":"My uncle works at a power plant outside the city.","vi":"Chú tôi làm việc ở một nhà máy điện ngoài thành phố."}]', '[{"phrase":"water the plants"},{"phrase":"power plant"},{"phrase":"house plant"}]', 'cũng là động từ: trồng (plant a tree)', '/plænt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plant/plant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 25, 'paint', 'sơn; vẽ (tranh)', 'verb', '[{"en":"We painted the kitchen walls light yellow.","vi":"Chúng tôi đã sơn tường bếp màu vàng nhạt."},{"en":"My sister likes to paint flowers and trees.","vi":"Em gái tôi thích vẽ hoa và cây."},{"en":"Are you going to paint the fence this weekend?","vi":"Cuối tuần này bạn có định sơn hàng rào không?"}]', '[{"phrase":"paint a picture"},{"phrase":"paint the walls"},{"phrase":"paint a room"}]', 'cũng là danh từ: sơn (wet paint)', '/peɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pai/paint/paint__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 26, 'worker', 'công nhân; người lao động', 'noun', '[{"en":"The factory hired two hundred new workers this year.","vi":"Năm nay nhà máy đã tuyển hai trăm công nhân mới."},{"en":"She is a hard worker and never misses a deadline.","vi":"Cô ấy là người làm việc chăm chỉ và không bao giờ trễ hạn."},{"en":"Office workers often eat lunch at their desks.","vi":"Nhân viên văn phòng thường ăn trưa ngay tại bàn làm việc."}]', '[{"phrase":"hard worker"},{"phrase":"office worker"},{"phrase":"factory worker"},{"phrase":"health workers"}]', NULL, '/ˈwɜːrkər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/worke/worker__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 27, 'press', 'nhấn; ấn; ép', 'verb', '[{"en":"Press the green button to start the machine.","vi":"Nhấn nút màu xanh để khởi động máy."},{"en":"She pressed her face against the window to see outside.","vi":"Cô ấy áp mặt vào cửa sổ để nhìn ra ngoài."},{"en":"He pressed the doorbell, but nobody answered.","vi":"Anh ấy bấm chuông cửa nhưng không ai trả lời."}]', '[{"phrase":"press a button"},{"phrase":"press a key"},{"phrase":"press hard"}]', 'cũng là danh từ: the press (báo chí)', '/pres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/press/press__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 28, 'whatever', 'bất cứ thứ gì; dù thế nào', 'pronoun', '[{"en":"You can order whatever you want from the menu.","vi":"Bạn có thể gọi bất cứ món gì bạn muốn trong thực đơn."},{"en":"Whatever happens, I''ll always be on your side.","vi":"Dù có chuyện gì xảy ra, tôi vẫn luôn ở bên bạn."},{"en":"She believes whatever her older brother tells her.","vi":"Anh trai nói gì cô ấy cũng tin."}]', '[{"phrase":"whatever you want"},{"phrase":"whatever happens"},{"phrase":"whatever it takes"}]', NULL, '/wətˈevər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wha/whate/whatever__us_3_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-06', 29, 'necessary', 'cần thiết', 'adjective', '[{"en":"Is it necessary to book a table in advance?","vi":"Có cần đặt bàn trước không?"},{"en":"Call me if necessary, even late at night.","vi":"Nếu cần thì gọi cho tôi, kể cả lúc khuya."},{"en":"The doctor said that surgery wasn''t necessary for my knee.","vi":"Bác sĩ nói đầu gối của tôi không cần thiết phải phẫu thuật."}]', '[{"phrase":"absolutely necessary"},{"phrase":"if necessary"},{"phrase":"necessary to do"},{"phrase":"necessary for"}]', NULL, '/ˈnesəseri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nec/neces/necessary__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-07', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 7', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 7);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 1, 'region', 'vùng; khu vực', 'noun', '[{"en":"This region is famous for its coffee and green hills.","vi":"Vùng này nổi tiếng với cà phê và những ngọn đồi xanh."},{"en":"Heavy rain is expected in the northern region tomorrow.","vi":"Dự báo ngày mai sẽ có mưa lớn ở khu vực phía bắc."},{"en":"Many people from rural regions move to big cities for work.","vi":"Nhiều người từ các vùng nông thôn chuyển lên thành phố lớn để làm việc."}]', '[{"phrase":"northern region"},{"phrase":"rural region"},{"phrase":"in the region"}]', NULL, '/ˈriːdʒən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regio/region__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 2, 'growth', 'sự tăng trưởng; sự phát triển', 'noun', '[{"en":"The company has seen strong growth over the past two years.","vi":"Công ty đã tăng trưởng mạnh trong hai năm qua."},{"en":"Good sleep is important for a child''s growth.","vi":"Ngủ ngon rất quan trọng cho sự phát triển của trẻ."},{"en":"Population growth has made housing in the city more expensive.","vi":"Sự gia tăng dân số đã khiến nhà ở trong thành phố đắt đỏ hơn."}]', '[{"phrase":"economic growth"},{"phrase":"strong growth"},{"phrase":"population growth"},{"phrase":"rapid growth"}]', NULL, '/ɡrəʊθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/growt/growth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 3, 'evening', 'buổi tối', 'noun', '[{"en":"I like to go for a walk in the evening.","vi":"Tôi thích đi dạo vào buổi tối."},{"en":"Are you free to meet for coffee on Friday evening?","vi":"Tối thứ Sáu bạn có rảnh đi uống cà phê không?"},{"en":"Thank you for a lovely evening with your family.","vi":"Cảm ơn bạn vì một buổi tối thật vui bên gia đình bạn."}]', '[{"phrase":"in the evening"},{"phrase":"this evening"},{"phrase":"Friday evening"},{"phrase":"spend the evening"}]', NULL, '/ˈiːvnɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/eveni/evening__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 4, 'influence', 'ảnh hưởng; tác động', 'noun', '[{"en":"My grandmother had a big influence on my life.","vi":"Bà tôi có ảnh hưởng lớn đến cuộc đời tôi."},{"en":"Parents should be aware of the influence of social media on teenagers.","vi":"Cha mẹ nên nhận thức được tác động của mạng xã hội đối với thanh thiếu niên."},{"en":"Her teachers have been a positive influence on her.","vi":"Thầy cô đã có ảnh hưởng tích cực đến cô ấy."}]', '[{"phrase":"have an influence on"},{"phrase":"strong influence"},{"phrase":"positive influence"}]', 'influence on sb/sth; cũng là động từ: influence sb', '/ˈɪnfluəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/influ/influence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 5, 'respect', 'sự tôn trọng; sự kính trọng', 'noun', '[{"en":"Children should show respect for their teachers.","vi":"Trẻ em nên kính trọng thầy cô giáo."},{"en":"She earned the respect of her team by working hard.","vi":"Cô ấy nhận được sự tôn trọng của cả nhóm nhờ làm việc chăm chỉ."},{"en":"We need to treat each other with respect.","vi":"Chúng ta cần đối xử tôn trọng với nhau."}]', '[{"phrase":"show respect"},{"phrase":"earn the respect"},{"phrase":"with respect"},{"phrase":"respect for"}]', 'respect for sb/sth; cũng là động từ: respect sb', '/rɪˈspekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respe/respect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 6, 'various', 'khác nhau; đa dạng', 'adjective', '[{"en":"The shop sells various kinds of tea from around the world.","vi":"Cửa hàng bán nhiều loại trà khác nhau từ khắp nơi trên thế giới."},{"en":"I tried calling her at various times, but she never answered.","vi":"Tôi đã thử gọi cho cô ấy vào nhiều lúc khác nhau nhưng cô ấy không bao giờ nghe máy."},{"en":"Students can join various clubs after school.","vi":"Học sinh có thể tham gia nhiều câu lạc bộ khác nhau sau giờ học."}]', '[{"phrase":"various kinds"},{"phrase":"various reasons"},{"phrase":"various ways"},{"phrase":"at various times"}]', NULL, '/ˈveriəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/vario/various__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 7, 'catch', 'bắt; kịp (xe, tàu); mắc (bệnh)', 'verb', '[{"en":"He caught the ball with one hand.","vi":"Anh ấy bắt quả bóng bằng một tay."},{"en":"We ran to catch the last bus home.","vi":"Chúng tôi chạy cho kịp chuyến xe buýt cuối cùng về nhà."},{"en":"I think I caught a cold from my little brother.","vi":"Tôi nghĩ mình bị lây cảm từ em trai."}]', '[{"phrase":"catch a ball"},{"phrase":"catch a bus"},{"phrase":"catch a cold"},{"phrase":"catch fish"}]', 'catch – caught – caught', '/kætʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/catch/catch__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 8, 'thus', 'vì vậy; do đó', 'adverb', '[{"en":"The train was delayed, and thus we missed the meeting.","vi":"Tàu bị trễ, do đó chúng tôi đã lỡ cuộc họp."},{"en":"She saved money every month and was thus able to buy a car.","vi":"Cô ấy tiết kiệm tiền hằng tháng, vì vậy đã mua được một chiếc xe hơi."},{"en":"The new system is faster and thus saves us a lot of time.","vi":"Hệ thống mới nhanh hơn và do đó giúp chúng tôi tiết kiệm nhiều thời gian."}]', '[{"phrase":"and thus"},{"phrase":"thus far"}]', 'trang trọng, thường dùng trong văn viết', '/ðʌs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thu/thus_/thus__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 9, 'skill', 'kỹ năng', 'noun', '[{"en":"Speaking in public is a skill you can learn.","vi":"Nói trước đám đông là một kỹ năng mà bạn có thể học được."},{"en":"This job requires good communication skills and a lot of patience.","vi":"Công việc này đòi hỏi kỹ năng giao tiếp tốt và rất nhiều kiên nhẫn."},{"en":"He wants to improve his cooking skills before moving out.","vi":"Anh ấy muốn cải thiện kỹ năng nấu ăn trước khi ra ở riêng."}]', '[{"phrase":"communication skills"},{"phrase":"improve your skills"},{"phrase":"learn a skill"},{"phrase":"language skills"}]', NULL, '/skɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/skill/skill__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 10, 'attempt', 'sự cố gắng; nỗ lực; lần thử', 'noun', '[{"en":"She passed her driving test on the first attempt.","vi":"Cô ấy thi đỗ bằng lái ngay từ lần đầu."},{"en":"In an attempt to save money, we stopped eating out.","vi":"Để cố gắng tiết kiệm tiền, chúng tôi đã thôi ăn ở ngoài."},{"en":"His attempt to fix the old radio was not successful.","vi":"Nỗ lực sửa chiếc radio cũ của anh ấy đã không thành công."}]', '[{"phrase":"make an attempt"},{"phrase":"first attempt"},{"phrase":"in an attempt to"},{"phrase":"failed attempt"}]', 'cũng là động từ: attempt to do sth', '/əˈtempt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attem/attempt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 11, 'son', 'con trai', 'noun', '[{"en":"Their son is starting university next month.","vi":"Con trai họ sẽ bắt đầu học đại học vào tháng sau."},{"en":"My oldest son loves playing football with his friends.","vi":"Con trai lớn của tôi rất thích chơi bóng đá với bạn bè."},{"en":"They have two daughters and a son.","vi":"Họ có hai con gái và một con trai."}]', '[{"phrase":"oldest son"},{"phrase":"only son"},{"phrase":"baby son"}]', NULL, '/sʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/son/son__/son__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 12, 'simple', 'đơn giản; dễ', 'adjective', '[{"en":"The instructions are simple, so anyone can follow them.","vi":"Hướng dẫn rất đơn giản nên ai cũng làm theo được."},{"en":"She prefers simple clothes in plain colors.","vi":"Cô ấy thích quần áo đơn giản, màu trơn."},{"en":"There is no simple answer to this question.","vi":"Câu hỏi này không có câu trả lời dễ dàng."}]', '[{"phrase":"simple answer"},{"phrase":"simple question"},{"phrase":"keep it simple"}]', NULL, '/ˈsɪmpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simpl/simple__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 13, 'medium', 'vừa; trung bình', 'adjective', '[{"en":"Can I have a medium coffee with milk, please?","vi":"Cho tôi một ly cà phê sữa cỡ vừa nhé."},{"en":"Cook the onions over medium heat for five minutes.","vi":"Xào hành trên lửa vừa trong năm phút."},{"en":"He is a man of medium height with short dark hair.","vi":"Anh ấy là người đàn ông cao trung bình, tóc ngắn màu sẫm."}]', '[{"phrase":"medium size"},{"phrase":"medium heat"},{"phrase":"medium height"}]', 'cũng là danh từ: phương tiện (truyền thông)', '/ˈmiːdiəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/mediu/medium__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 14, 'average', 'trung bình; bình thường', 'adjective', '[{"en":"The average price of a house here has doubled.","vi":"Giá nhà trung bình ở đây đã tăng gấp đôi."},{"en":"She is taller than the average girl her age.","vi":"Cô bé cao hơn mức trung bình của các bạn gái cùng tuổi."},{"en":"It was just an average day at the office.","vi":"Đó chỉ là một ngày bình thường ở văn phòng."}]', '[{"phrase":"average price"},{"phrase":"average age"},{"phrase":"average temperature"},{"phrase":"above average"}]', NULL, '/ˈævərɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ave/avera/average__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 15, 'stock', 'hàng trong kho; cổ phiếu', 'noun', '[{"en":"Sorry, those shoes are out of stock in your size.","vi":"Xin lỗi, đôi giày đó đã hết hàng cỡ của bạn."},{"en":"The shop keeps a large stock of winter coats.","vi":"Cửa hàng luôn có sẵn một lượng lớn áo khoác mùa đông."},{"en":"My uncle invested some of his savings in stocks.","vi":"Chú tôi đã đầu tư một phần tiền tiết kiệm vào cổ phiếu."}]', '[{"phrase":"out of stock"},{"phrase":"in stock"},{"phrase":"stock market"}]', NULL, '/stɑːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stock/stock__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 16, 'management', 'sự quản lý; ban quản lý', 'noun', '[{"en":"Good time management helps students reduce stress.","vi":"Quản lý thời gian tốt giúp học sinh giảm căng thẳng."},{"en":"The hotel is now under new management.","vi":"Khách sạn giờ đã đổi sang ban quản lý mới."},{"en":"She wants to study business management at university.","vi":"Cô ấy muốn học quản trị kinh doanh ở đại học."}]', '[{"phrase":"time management"},{"phrase":"under new management"},{"phrase":"business management"},{"phrase":"senior management"}]', NULL, '/ˈmænɪdʒmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manag/management__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 17, 'character', 'tính cách; nhân vật', 'noun', '[{"en":"My brother and I have very different characters.","vi":"Anh trai tôi và tôi có tính cách rất khác nhau."},{"en":"She has a strong character and never gives up easily.","vi":"Cô ấy có tính cách mạnh mẽ và không bao giờ dễ dàng bỏ cuộc."},{"en":"Who is your favorite character in the movie?","vi":"Nhân vật yêu thích của bạn trong bộ phim là ai?"}]', '[{"phrase":"main character"},{"phrase":"strong character"},{"phrase":"favorite character"}]', NULL, '/ˈkærəktər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chara/character__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 18, 'bed', 'giường', 'noun', '[{"en":"I usually go to bed before eleven o''clock.","vi":"Tôi thường đi ngủ trước mười một giờ."},{"en":"Please make your bed before you leave for school.","vi":"Con hãy dọn giường trước khi đi học nhé."},{"en":"The hotel room has two single beds and a small desk.","vi":"Phòng khách sạn có hai giường đơn và một chiếc bàn nhỏ."}]', '[{"phrase":"go to bed"},{"phrase":"make the bed"},{"phrase":"single bed"},{"phrase":"double bed"}]', NULL, '/bed/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bed/bed__/bed__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 19, 'hit', 'đánh; va vào; đâm vào', 'verb', '[{"en":"He hit the ball over the fence.","vi":"Anh ấy đánh quả bóng bay qua hàng rào."},{"en":"I hit my head on the kitchen cabinet this morning.","vi":"Sáng nay tôi bị đập đầu vào tủ bếp."},{"en":"The delivery truck hit our gate while it was turning around.","vi":"Xe tải giao hàng đã tông vào cổng nhà chúng tôi khi đang quay đầu."}]', '[{"phrase":"hit the ball"},{"phrase":"hit your head"},{"phrase":"hit hard"}]', 'hit – hit – hit', '/hɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hit/hit__/hit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 20, 'establish', 'thành lập; thiết lập, tạo dựng', 'verb', '[{"en":"The school was established more than a hundred years ago.","vi":"Ngôi trường được thành lập cách đây hơn một trăm năm."},{"en":"My grandfather established the family business in 1985.","vi":"Ông tôi thành lập doanh nghiệp gia đình vào năm 1985."},{"en":"It takes time to establish trust with new coworkers.","vi":"Cần có thời gian để tạo dựng lòng tin với đồng nghiệp mới."}]', '[{"phrase":"establish a business"},{"phrase":"establish trust"},{"phrase":"establish a relationship"},{"phrase":"be established in"}]', NULL, '/ɪˈstæblɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estab/establish__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 21, 'indeed', 'thật vậy; quả thật', 'adverb', '[{"en":"It was indeed a very difficult decision for our family.","vi":"Đó quả thật là một quyết định rất khó khăn đối với gia đình chúng tôi."},{"en":"Thank you, the meal was very good indeed.","vi":"Cảm ơn bạn, bữa ăn thật sự rất ngon."},{"en":"Many people thought the test would be easy, and indeed it was.","vi":"Nhiều người nghĩ bài kiểm tra sẽ dễ, và quả thật là vậy."}]', '[{"phrase":"very good indeed"},{"phrase":"yes, indeed"},{"phrase":"and indeed"}]', 'very + tính từ + indeed: nhấn mạnh', '/ɪnˈdiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indee/indeed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 22, 'final', 'cuối cùng; chung cuộc', 'adjective', '[{"en":"This is your final chance to sign up for the trip.","vi":"Đây là cơ hội cuối cùng để bạn đăng ký chuyến đi."},{"en":"The final exam will be held on June 20.","vi":"Kỳ thi cuối kỳ sẽ được tổ chức vào ngày 20 tháng 6."},{"en":"The final score was two to one.","vi":"Tỷ số chung cuộc là 2–1."}]', '[{"phrase":"final exam"},{"phrase":"final decision"},{"phrase":"final chance"},{"phrase":"final score"}]', NULL, '/ˈfaɪnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/final/final__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 23, 'economy', 'nền kinh tế', 'noun', '[{"en":"Tourism is very important to the local economy.","vi":"Du lịch rất quan trọng đối với nền kinh tế địa phương."},{"en":"The economy grew quickly over the last ten years.","vi":"Nền kinh tế đã tăng trưởng nhanh trong mười năm qua."},{"en":"Many small businesses closed when the economy slowed down.","vi":"Nhiều doanh nghiệp nhỏ đã đóng cửa khi nền kinh tế chững lại."}]', '[{"phrase":"local economy"},{"phrase":"global economy"},{"phrase":"strong economy"}]', NULL, '/ɪˈkɑːnəmi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eco/econo/economy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 24, 'fit', 'vừa; vừa với; sắp xếp được (thời gian)', 'verb', '[{"en":"These jeans don''t fit me anymore, so I need new ones.","vi":"Chiếc quần jean này không còn vừa với tôi nữa nên tôi cần quần mới."},{"en":"Will all this luggage fit in the back of your car?","vi":"Chỗ hành lý này có để vừa phía sau xe của bạn không?"},{"en":"The doctor can fit you in at three o''clock tomorrow.","vi":"Bác sĩ có thể sắp xếp khám cho bạn lúc ba giờ ngày mai."}]', '[{"phrase":"fit perfectly"},{"phrase":"fit in"},{"phrase":"fit into"},{"phrase":"fit well"}]', 'Mỹ: fit – fit – fit · Anh: fit – fitted – fitted', '/fɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fit/fit__/fit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 25, 'guy', 'anh chàng; gã', 'noun', '[{"en":"The guy at the front desk was really helpful.","vi":"Anh chàng ở quầy lễ tân rất nhiệt tình giúp đỡ."},{"en":"He seems like a nice guy, but I don''t know him well.","vi":"Anh ấy có vẻ là người tốt, nhưng tôi không biết rõ về anh ấy."},{"en":"Are you guys coming to the party tonight?","vi":"Các bạn có đến bữa tiệc tối nay không?"}]', '[{"phrase":"nice guy"},{"phrase":"good guy"},{"phrase":"you guys"}]', 'thân mật; you guys = các bạn', '/ɡaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/guy/guy__/guy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 26, 'function', 'chức năng', 'noun', '[{"en":"This app has a useful function for tracking your spending.","vi":"Ứng dụng này có một chức năng hữu ích để theo dõi chi tiêu."},{"en":"The main function of the heart is to pump blood.","vi":"Chức năng chính của tim là bơm máu."},{"en":"Regular exercise helps improve brain function in older people.","vi":"Tập thể dục thường xuyên giúp cải thiện chức năng não ở người lớn tuổi."}]', '[{"phrase":"main function"},{"phrase":"brain function"},{"phrase":"basic function"},{"phrase":"perform a function"}]', NULL, '/ˈfʌŋkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funct/function__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 27, 'yesterday', 'hôm qua', 'adverb', '[{"en":"I saw your sister at the supermarket yesterday morning.","vi":"Sáng hôm qua tôi gặp chị gái bạn ở siêu thị."},{"en":"Yesterday was the hottest day of the year so far.","vi":"Hôm qua là ngày nóng nhất trong năm tính đến nay."},{"en":"Did you finish the report I sent you yesterday?","vi":"Bạn đã làm xong bản báo cáo tôi gửi hôm qua chưa?"}]', '[{"phrase":"yesterday morning"},{"phrase":"yesterday afternoon"},{"phrase":"the day before yesterday"}]', NULL, '/ˈjestərdeɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yes/yeste/yesterday__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 28, 'image', 'hình ảnh; hình tượng', 'noun', '[{"en":"The images on this website are very clear.","vi":"Hình ảnh trên trang web này rất rõ nét."},{"en":"The company wants to improve its public image.","vi":"Công ty muốn cải thiện hình ảnh trước công chúng."},{"en":"I still have a clear image of my first day at school.","vi":"Tôi vẫn nhớ rõ hình ảnh ngày đầu tiên đi học."}]', '[{"phrase":"public image"},{"phrase":"clear image"},{"phrase":"digital image"}]', NULL, '/ˈɪmɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/image/image__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-07', 29, 'size', 'kích cỡ; cỡ', 'noun', '[{"en":"Do you have these shoes in a bigger size?","vi":"Bạn có đôi giày này cỡ lớn hơn không?"},{"en":"Their new apartment is about twice the size of ours.","vi":"Căn hộ mới của họ rộng khoảng gấp đôi căn hộ của chúng tôi."},{"en":"The size of each class is limited to twenty students.","vi":"Sĩ số mỗi lớp được giới hạn ở hai mươi học sinh."}]', '[{"phrase":"shoe size"},{"phrase":"bigger size"},{"phrase":"the size of"},{"phrase":"twice the size"}]', NULL, '/saɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/siz/size_/size__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-08', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 8', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 8);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 1, 'behavior', 'hành vi; cách cư xử', 'noun', '[{"en":"The teacher praised the children for their good behavior in class.","vi":"Cô giáo khen bọn trẻ vì đã cư xử ngoan trong lớp."},{"en":"I''m sorry about my behavior at the party last night.","vi":"Tôi xin lỗi về cách cư xử của mình ở bữa tiệc tối qua."},{"en":"Scientists study the behavior of animals in the wild.","vi":"Các nhà khoa học nghiên cứu hành vi của động vật trong tự nhiên."}]', '[{"phrase":"good behavior"},{"phrase":"bad behavior"},{"phrase":"animal behavior"},{"phrase":"change behavior"}]', 'Anh: behaviour · Mỹ: behavior', '/bɪˈheɪvjər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 2, 'addition', 'sự thêm vào; phần bổ sung; phép cộng', 'noun', '[{"en":"In addition to English, she speaks French and Japanese.","vi":"Ngoài tiếng Anh, cô ấy còn nói được tiếng Pháp và tiếng Nhật."},{"en":"The new kitchen is a great addition to our house.","vi":"Căn bếp mới là một phần bổ sung tuyệt vời cho ngôi nhà của chúng tôi."},{"en":"My son is learning addition and subtraction at school.","vi":"Con trai tôi đang học phép cộng và phép trừ ở trường."}]', '[{"phrase":"in addition"},{"phrase":"in addition to"},{"phrase":"a welcome addition"},{"phrase":"a new addition"}]', 'in addition to + N/V-ing: ngoài … ra', '/əˈdɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/addit/addition__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 3, 'determine', 'xác định; quyết định', 'verb', '[{"en":"Doctors are trying to determine the cause of her illness.","vi":"Các bác sĩ đang cố xác định nguyên nhân gây bệnh của cô ấy."},{"en":"Police have not yet determined how the fire started.","vi":"Cảnh sát vẫn chưa xác định được đám cháy bắt đầu như thế nào."},{"en":"Your grades will determine which university you can attend.","vi":"Điểm số của bạn sẽ quyết định bạn có thể vào trường đại học nào."}]', '[{"phrase":"determine the cause"},{"phrase":"help determine"},{"phrase":"determine whether"}]', NULL, '/dɪˈtɜːrmɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/deter/determine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 4, 'station', 'nhà ga; trạm; bến (xe)', 'noun', '[{"en":"I''ll meet you at the train station at six o''clock.","vi":"Tôi sẽ gặp bạn ở ga tàu lúc sáu giờ."},{"en":"We stopped at a gas station to buy some snacks.","vi":"Chúng tôi dừng ở một trạm xăng để mua ít đồ ăn vặt."},{"en":"How far is the nearest bus station from here?","vi":"Bến xe buýt gần nhất cách đây bao xa?"}]', '[{"phrase":"train station"},{"phrase":"bus station"},{"phrase":"gas station"},{"phrase":"police station"}]', NULL, '/ˈsteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stati/station__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 5, 'population', 'dân số; dân cư', 'noun', '[{"en":"The population of the city has doubled in twenty years.","vi":"Dân số của thành phố đã tăng gấp đôi trong hai mươi năm."},{"en":"Our town has a population of about fifty thousand.","vi":"Thị trấn của chúng tôi có dân số khoảng năm mươi nghìn người."},{"en":"Most of the population lives near the coast.","vi":"Phần lớn dân cư sống gần bờ biển."}]', '[{"phrase":"large population"},{"phrase":"growing population"},{"phrase":"population growth"},{"phrase":"world population"}]', NULL, '/ˌpɑːpjuˈleɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pop/popul/population__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 6, 'fail', 'thất bại; trượt (kỳ thi); không làm được', 'verb', '[{"en":"He failed his driving test for the second time.","vi":"Anh ấy trượt bài thi lái xe lần thứ hai."},{"en":"Our first plan failed, so we tried something different.","vi":"Kế hoạch đầu tiên của chúng tôi thất bại, nên chúng tôi đã thử cách khác."},{"en":"The bus failed to arrive on time again this morning.","vi":"Sáng nay xe buýt lại không đến đúng giờ."}]', '[{"phrase":"fail a test"},{"phrase":"fail an exam"},{"phrase":"fail completely"}]', 'fail to do sth: không làm được việc gì', '/feɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/fail_/fail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 7, 'environment', 'môi trường', 'noun', '[{"en":"We should all do more to protect the environment.","vi":"Tất cả chúng ta nên làm nhiều hơn để bảo vệ môi trường."},{"en":"Children learn best in a safe and happy environment.","vi":"Trẻ em học tốt nhất trong một môi trường an toàn và vui vẻ."},{"en":"Plastic bags are really bad for the environment.","vi":"Túi ni lông thực sự có hại cho môi trường."}]', '[{"phrase":"protect the environment"},{"phrase":"work environment"},{"phrase":"safe environment"},{"phrase":"natural environment"}]', NULL, '/ɪnˈvaɪrənmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envir/environment__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 8, 'production', 'sự sản xuất; sản lượng', 'noun', '[{"en":"The factory increased production to meet the high demand.","vi":"Nhà máy đã tăng sản lượng để đáp ứng nhu cầu cao."},{"en":"Rice production in the region fell because of the drought.","vi":"Sản lượng lúa gạo trong vùng giảm vì hạn hán."},{"en":"Production of the new phone will start next month.","vi":"Việc sản xuất mẫu điện thoại mới sẽ bắt đầu vào tháng sau."}]', '[{"phrase":"increase production"},{"phrase":"food production"},{"phrase":"mass production"},{"phrase":"production costs"}]', NULL, '/prəˈdʌkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/production__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 9, 'contract', 'hợp đồng', 'noun', '[{"en":"She signed a two-year contract with a local company.","vi":"Cô ấy đã ký hợp đồng hai năm với một công ty địa phương."},{"en":"Please read the contract carefully before you sign it.","vi":"Vui lòng đọc kỹ hợp đồng trước khi ký."},{"en":"His contract ends in December, so he''s looking for a new job.","vi":"Hợp đồng của anh ấy hết hạn vào tháng Mười Hai, nên anh ấy đang tìm việc mới."}]', '[{"phrase":"sign a contract"},{"phrase":"break a contract"},{"phrase":"employment contract"},{"phrase":"under contract"}]', NULL, '/ˈkɑːntrækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontract__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 10, 'player', 'người chơi; cầu thủ', 'noun', '[{"en":"He is the best player on our school''s soccer team.","vi":"Cậu ấy là cầu thủ giỏi nhất trong đội bóng đá của trường chúng tôi."},{"en":"This board game needs at least four players.","vi":"Trò chơi cờ bàn này cần ít nhất bốn người chơi."},{"en":"My sister is a talented piano player.","vi":"Chị tôi là một người chơi piano có tài."}]', '[{"phrase":"soccer player"},{"phrase":"tennis player"},{"phrase":"key player"},{"phrase":"piano player"}]', NULL, '/ˈpleɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/playe/player__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 11, 'comment', 'lời bình luận; lời nhận xét', 'noun', '[{"en":"Thanks for your helpful comments on my essay.","vi":"Cảm ơn những nhận xét hữu ích của bạn về bài luận của tôi."},{"en":"She made a rude comment about my new haircut.","vi":"Cô ấy đưa ra một lời nhận xét bất lịch sự về kiểu tóc mới của tôi."},{"en":"Hundreds of people left comments under the video.","vi":"Hàng trăm người đã để lại bình luận dưới video."}]', '[{"phrase":"make a comment"},{"phrase":"leave a comment"},{"phrase":"no comment"}]', NULL, '/ˈkɑːment/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/comment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 12, 'enter', 'đi vào; nhập (dữ liệu); tham gia (cuộc thi)', 'verb', '[{"en":"Please knock before you enter the room.","vi":"Vui lòng gõ cửa trước khi vào phòng."},{"en":"Enter your password and click the blue button.","vi":"Hãy nhập mật khẩu và nhấn vào nút màu xanh."},{"en":"She entered a cooking competition and won second prize.","vi":"Cô ấy tham gia một cuộc thi nấu ăn và giành giải nhì."}]', '[{"phrase":"enter the room"},{"phrase":"enter a password"},{"phrase":"enter a competition"},{"phrase":"enter the country"}]', 'enter the room (không nói "enter into the room")', '/ˈentər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/enter__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 13, 'occur', 'xảy ra; nảy ra (trong đầu)', 'verb', '[{"en":"The accident occurred on a busy road near the school.","vi":"Vụ tai nạn xảy ra trên một con đường đông đúc gần trường học."},{"en":"Please tell us if the problem occurs again.","vi":"Vui lòng báo cho chúng tôi nếu sự cố lại xảy ra."},{"en":"It never occurred to me that she might be lonely.","vi":"Tôi chưa bao giờ nghĩ đến việc cô ấy có thể đang cô đơn."}]', '[{"phrase":"occur naturally"},{"phrase":"problems occur"},{"phrase":"it occurred to me"}]', 'occurred, occurring (gấp đôi r); occur to sb: chợt nghĩ ra', '/əˈkɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occur/occur__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 14, 'alone', 'một mình', 'adverb', '[{"en":"My grandmother lives alone, so I visit her every weekend.","vi":"Bà tôi sống một mình, nên cuối tuần nào tôi cũng đến thăm bà."},{"en":"I don''t like being alone in the house at night.","vi":"Tôi không thích ở nhà một mình vào ban đêm."},{"en":"Is it safe for a woman to travel alone?","vi":"Phụ nữ đi du lịch một mình có an toàn không?"}]', '[{"phrase":"live alone"},{"phrase":"travel alone"},{"phrase":"leave me alone"},{"phrase":"all alone"}]', NULL, '/əˈləʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alo/alone/alone__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 15, 'significant', 'đáng kể; quan trọng', 'adjective', '[{"en":"There has been a significant increase in house prices this year.","vi":"Năm nay giá nhà đã tăng đáng kể."},{"en":"Moving abroad was the most significant decision of my life.","vi":"Chuyển ra nước ngoài là quyết định quan trọng nhất trong đời tôi."},{"en":"The new medicine made a significant difference to his health.","vi":"Loại thuốc mới đã tạo ra sự khác biệt đáng kể cho sức khỏe của anh ấy."}]', '[{"phrase":"significant increase"},{"phrase":"significant difference"},{"phrase":"significant change"},{"phrase":"significant role"}]', NULL, '/sɪɡˈnɪfɪkənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 16, 'drug', 'thuốc; ma túy', 'noun', '[{"en":"This drug helps to reduce pain and fever.","vi":"Loại thuốc này giúp giảm đau và hạ sốt."},{"en":"Scientists are developing a new drug to treat the disease.","vi":"Các nhà khoa học đang phát triển một loại thuốc mới để điều trị căn bệnh này."},{"en":"Taking drugs can seriously damage your health.","vi":"Sử dụng ma túy có thể gây hại nghiêm trọng cho sức khỏe của bạn."}]', '[{"phrase":"take drugs"},{"phrase":"drug use"},{"phrase":"prescription drug"},{"phrase":"new drug"}]', NULL, '/drʌɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dru/drug_/drug__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 17, 'wall', 'bức tường', 'noun', '[{"en":"We hung a big family photo on the living room wall.","vi":"Chúng tôi treo một tấm ảnh gia đình lớn trên tường phòng khách."},{"en":"The children painted the walls of their bedroom bright blue.","vi":"Bọn trẻ sơn tường phòng ngủ của chúng màu xanh dương sáng."},{"en":"An old stone wall runs around the garden.","vi":"Một bức tường đá cũ bao quanh khu vườn."}]', '[{"phrase":"on the wall"},{"phrase":"paint a wall"},{"phrase":"stone wall"},{"phrase":"brick wall"}]', NULL, '/wɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wal/wall_/wall__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 18, 'series', 'loạt; chuỗi; phim dài tập', 'noun', '[{"en":"We watched the whole TV series in one weekend.","vi":"Chúng tôi đã xem hết cả bộ phim truyền hình dài tập trong một cuối tuần."},{"en":"The company had a series of problems last year.","vi":"Năm ngoái công ty gặp phải một loạt vấn đề."},{"en":"She is giving a series of talks on healthy eating.","vi":"Cô ấy đang có một loạt bài nói chuyện về ăn uống lành mạnh."}]', '[{"phrase":"a series of"},{"phrase":"TV series"},{"phrase":"a series of events"}]', 'số ít và số nhiều giống nhau: series', '/ˈsɪriːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serie/series__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 19, 'direct', 'trực tiếp; thẳng; thẳng thắn', 'adjective', '[{"en":"Is there a direct flight from Hanoi to London?","vi":"Có chuyến bay thẳng từ Hà Nội đến Luân Đôn không?"},{"en":"Keep the plant out of direct sunlight.","vi":"Hãy để cây tránh ánh nắng trực tiếp."},{"en":"I''d prefer a direct answer, not a long explanation.","vi":"Tôi muốn một câu trả lời thẳng thắn, chứ không phải một lời giải thích dài dòng."}]', '[{"phrase":"direct flight"},{"phrase":"direct sunlight"},{"phrase":"direct contact"}]', NULL, '/dəˈrekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/direct__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 20, 'success', 'sự thành công', 'noun', '[{"en":"The party was a great success, and everyone had fun.","vi":"Bữa tiệc rất thành công và mọi người đều vui vẻ."},{"en":"Hard work is the key to success.","vi":"Chăm chỉ là chìa khóa dẫn đến thành công."},{"en":"We wish you every success in your new job.","vi":"Chúc bạn mọi thành công trong công việc mới."}]', '[{"phrase":"great success"},{"phrase":"key to success"},{"phrase":"achieve success"}]', NULL, '/səkˈses/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/success__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 21, 'tomorrow', 'ngày mai', 'adverb', '[{"en":"I have an important meeting at nine tomorrow morning.","vi":"Tôi có một cuộc họp quan trọng lúc chín giờ sáng mai."},{"en":"Can we talk about this tomorrow when I''m less tired?","vi":"Mai chúng ta nói về chuyện này khi tôi đỡ mệt hơn được không?"},{"en":"Tomorrow will be sunny, so let''s go to the park.","vi":"Ngày mai trời sẽ nắng, vậy chúng ta đi công viên nhé."}]', '[{"phrase":"tomorrow morning"},{"phrase":"tomorrow night"},{"phrase":"see you tomorrow"},{"phrase":"the day after tomorrow"}]', NULL, '/təˈmɑːrəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tom/tomor/tomorrow__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 22, 'director', 'giám đốc; đạo diễn', 'noun', '[{"en":"She was promoted to sales director last year.","vi":"Năm ngoái cô ấy được thăng chức làm giám đốc kinh doanh."},{"en":"The director of the film won several awards.","vi":"Đạo diễn của bộ phim đã giành được nhiều giải thưởng."},{"en":"You should send your report to the finance director.","vi":"Bạn nên gửi báo cáo cho giám đốc tài chính."}]', '[{"phrase":"managing director"},{"phrase":"film director"},{"phrase":"sales director"},{"phrase":"board of directors"}]', NULL, '/dəˈrektər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/director__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 23, 'clearly', 'rõ ràng; rõ', 'adverb', '[{"en":"Please speak clearly so everyone can hear you.","vi":"Vui lòng nói rõ ràng để mọi người đều có thể nghe thấy bạn."},{"en":"Without my glasses, I can''t see clearly.","vi":"Không có kính, tôi không nhìn rõ được."},{"en":"She was clearly upset about the news.","vi":"Rõ ràng là cô ấy buồn vì tin đó."}]', '[{"phrase":"speak clearly"},{"phrase":"see clearly"},{"phrase":"think clearly"},{"phrase":"clearly visible"}]', NULL, '/ˈklɪrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cle/clear/clearly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 24, 'lack', 'sự thiếu; thiếu', 'noun', '[{"en":"Lack of sleep can make it hard to concentrate.","vi":"Thiếu ngủ có thể khiến bạn khó tập trung."},{"en":"The project failed because of a lack of money.","vi":"Dự án thất bại vì thiếu tiền."},{"en":"He lacks confidence when he speaks in public.","vi":"Anh ấy thiếu tự tin khi nói trước đám đông."}]', '[{"phrase":"lack of sleep"},{"phrase":"lack of money"},{"phrase":"lack of time"},{"phrase":"lack confidence"}]', 'danh từ: lack of + N; động từ: lack + N (không có "of")', '/læk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lac/lack_/lack__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 25, 'review', 'bài đánh giá; sự xem xét lại', 'noun', '[{"en":"I always read online reviews before I book a hotel.","vi":"Tôi luôn đọc các bài đánh giá trên mạng trước khi đặt khách sạn."},{"en":"The movie got great reviews from critics.","vi":"Bộ phim nhận được những lời đánh giá rất tốt từ giới phê bình."},{"en":"The company is doing a review of its safety rules.","vi":"Công ty đang xem xét lại các quy định an toàn của mình."}]', '[{"phrase":"write a review"},{"phrase":"good reviews"},{"phrase":"under review"}]', NULL, '/rɪˈvjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revie/review__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 26, 'depend', 'phụ thuộc; dựa vào; trông cậy', 'verb', '[{"en":"Whether we go to the beach depends on the weather.","vi":"Chúng tôi có đi biển hay không còn phụ thuộc vào thời tiết."},{"en":"Many old people depend on their children for help.","vi":"Nhiều người già dựa vào con cái để được giúp đỡ."},{"en":"You can always depend on me when you need a friend.","vi":"Bạn luôn có thể trông cậy vào tôi khi cần một người bạn."}]', '[{"phrase":"depend on"},{"phrase":"it depends"},{"phrase":"depend heavily on"}]', 'depend on/upon sb/sth', '/dɪˈpend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depen/depend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 27, 'race', 'cuộc đua; cuộc chạy đua', 'noun', '[{"en":"She came second in the 100-meter race.","vi":"Cô ấy về nhì trong cuộc đua 100 mét."},{"en":"My brother won his first bike race last Sunday.","vi":"Anh trai tôi đã thắng cuộc đua xe đạp đầu tiên vào Chủ nhật tuần trước."},{"en":"We''re in a race against time to finish the project.","vi":"Chúng tôi đang chạy đua với thời gian để hoàn thành dự án."}]', '[{"phrase":"win a race"},{"phrase":"lose a race"},{"phrase":"horse race"},{"phrase":"a race against time"}]', NULL, '/reɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rac/race_/race__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 28, 'recognize', 'nhận ra; công nhận', 'verb', '[{"en":"I didn''t recognize you with your new haircut!","vi":"Tôi đã không nhận ra bạn với kiểu tóc mới!"},{"en":"Would you recognize the man if you saw him again?","vi":"Bạn có nhận ra người đàn ông đó nếu gặp lại anh ta không?"},{"en":"Her hard work was finally recognized with an award.","vi":"Sự chăm chỉ của cô ấy cuối cùng đã được công nhận bằng một giải thưởng."}]', '[{"phrase":"recognize someone"},{"phrase":"immediately recognize"},{"phrase":"widely recognized"},{"phrase":"recognize the importance"}]', 'Anh: recognise · Mỹ: recognize', '/ˈrekəɡnaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recog/recognize__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-08', 29, 'window', 'cửa sổ', 'noun', '[{"en":"Do you mind if I open the window for some air?","vi":"Bạn có phiền không nếu tôi mở cửa sổ cho thoáng khí?"},{"en":"Our hotel room had a window with a view of the sea.","vi":"Phòng khách sạn của chúng tôi có cửa sổ nhìn ra biển."},{"en":"The kids broke the kitchen window while playing soccer.","vi":"Bọn trẻ làm vỡ cửa sổ nhà bếp khi đang chơi bóng đá."}]', '[{"phrase":"open the window"},{"phrase":"close the window"},{"phrase":"look out the window"},{"phrase":"window seat"}]', NULL, '/ˈwɪndəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/windo/window__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-09', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 9', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 9);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 1, 'purpose', 'mục đích', 'noun', '[{"en":"What is the purpose of your visit to Vietnam?","vi":"Mục đích chuyến đi Việt Nam của bạn là gì?"},{"en":"I don''t think he broke the glass on purpose.","vi":"Tôi không nghĩ anh ấy cố ý làm vỡ cái ly."},{"en":"The main purpose of this meeting is to plan next month''s budget.","vi":"Mục đích chính của cuộc họp này là lên kế hoạch ngân sách cho tháng sau."}]', '[{"phrase":"main purpose"},{"phrase":"on purpose"},{"phrase":"serve a purpose"}]', 'on purpose = cố ý', '/ˈpɜːrpəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/purpo/purpose__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 2, 'department', 'phòng, ban; khoa', 'noun', '[{"en":"She works in the sales department of a large company.","vi":"Cô ấy làm việc ở phòng kinh doanh của một công ty lớn."},{"en":"My brother teaches in the history department at the university.","vi":"Anh trai tôi giảng dạy ở khoa lịch sử của trường đại học."},{"en":"Please send your questions to the human resources department by Friday.","vi":"Vui lòng gửi câu hỏi của bạn đến phòng nhân sự trước thứ Sáu."}]', '[{"phrase":"sales department"},{"phrase":"head of department"},{"phrase":"department store"}]', NULL, '/dɪˈpɑːrtmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depar/department__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 3, 'gain', 'có được, giành được; tăng (cân)', 'verb', '[{"en":"She gained a lot of experience from her first job.","vi":"Cô ấy đã có được nhiều kinh nghiệm từ công việc đầu tiên."},{"en":"I gained five kilos during the holidays.","vi":"Tôi đã tăng năm ký trong kỳ nghỉ lễ."},{"en":"The new manager slowly gained the trust of her team.","vi":"Người quản lý mới dần dần giành được sự tin tưởng của nhóm mình."}]', '[{"phrase":"gain experience"},{"phrase":"gain weight"},{"phrase":"gain confidence"}]', NULL, '/ɡeɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gai/gain_/gain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 4, 'tree', 'cây', 'noun', '[{"en":"The children are sitting in the shade of a big tree.","vi":"Bọn trẻ đang ngồi dưới bóng một cái cây lớn."},{"en":"We planted an apple tree in our garden last spring.","vi":"Chúng tôi đã trồng một cây táo trong vườn vào mùa xuân năm ngoái."},{"en":"A strong wind knocked down several trees near the school.","vi":"Một cơn gió mạnh đã quật đổ vài cái cây gần trường."}]', '[{"phrase":"plant a tree"},{"phrase":"apple tree"},{"phrase":"climb a tree"}]', NULL, '/triː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/tree_/tree__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 5, 'college', 'trường cao đẳng; đại học', 'noun', '[{"en":"My sister wants to go to college and study medicine.","vi":"Em gái tôi muốn vào đại học để học ngành y."},{"en":"He met his wife when they were both in college.","vi":"Anh ấy gặp vợ mình khi cả hai còn đang học đại học."},{"en":"She is taking an evening course at the local community college.","vi":"Cô ấy đang học một khóa buổi tối tại trường cao đẳng cộng đồng ở địa phương."}]', '[{"phrase":"go to college"},{"phrase":"college student"},{"phrase":"college degree"}]', NULL, '/ˈkɑːlɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/college__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 6, 'argue', 'cãi nhau; lập luận, cho rằng', 'verb', '[{"en":"My parents sometimes argue about money, but they never shout.","vi":"Bố mẹ tôi thỉnh thoảng cãi nhau về tiền bạc, nhưng họ không bao giờ quát tháo."},{"en":"Stop arguing with your brother and finish your dinner.","vi":"Đừng cãi nhau với anh con nữa, ăn nốt bữa tối đi."},{"en":"Some people argue that working from home makes us more productive.","vi":"Một số người cho rằng làm việc tại nhà giúp chúng ta làm việc hiệu quả hơn."}]', '[{"phrase":"argue with"},{"phrase":"argue about"},{"phrase":"argue that"}]', NULL, '/ˈɑːrɡjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arg/argue/argue__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 7, 'board', 'tấm bảng; ban, hội đồng', 'noun', '[{"en":"The teacher wrote the new words on the board.","vi":"Giáo viên viết những từ mới lên bảng."},{"en":"Check the notice board for the new exam schedule.","vi":"Hãy xem bảng thông báo để biết lịch thi mới."},{"en":"The board of directors will meet next week to discuss the plan.","vi":"Hội đồng quản trị sẽ họp vào tuần tới để thảo luận kế hoạch."}]', '[{"phrase":"notice board"},{"phrase":"board of directors"},{"phrase":"on board"}]', NULL, '/bɔːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boa/board/board__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 8, 'holiday', 'kỳ nghỉ; ngày lễ', 'noun', '[{"en":"We spent our summer holiday at the beach with my grandparents.","vi":"Chúng tôi đã dành kỳ nghỉ hè ở biển cùng ông bà."},{"en":"Banks and schools are closed on public holidays.","vi":"Ngân hàng và trường học đóng cửa vào các ngày lễ."},{"en":"My boss is on holiday until next Monday.","vi":"Sếp tôi đi nghỉ đến thứ Hai tuần sau."}]', '[{"phrase":"summer holiday"},{"phrase":"public holiday"},{"phrase":"on holiday"},{"phrase":"go on holiday"}]', 'Anh: holiday · Mỹ: vacation (kỳ nghỉ)', '/ˈhɑːlədeɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/holid/holiday__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 9, 'mark', 'vết, dấu; điểm (bài thi)', 'noun', '[{"en":"The hot cup left a mark on the wooden table.","vi":"Cái cốc nóng để lại một vết trên bàn gỗ."},{"en":"She got top marks in every subject this year.","vi":"Năm nay cô ấy đạt điểm cao nhất ở tất cả các môn."},{"en":"Put a question mark at the end of the sentence.","vi":"Hãy đặt dấu chấm hỏi ở cuối câu."}]', '[{"phrase":"question mark"},{"phrase":"top marks"},{"phrase":"leave a mark"}]', NULL, '/mɑːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/mark_/mark__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 10, 'church', 'nhà thờ', 'noun', '[{"en":"There is an old stone church in the center of the village.","vi":"Có một nhà thờ cổ bằng đá ở trung tâm ngôi làng."},{"en":"They got married in a small church near the sea.","vi":"Họ đã kết hôn tại một nhà thờ nhỏ gần biển."},{"en":"We could hear the church bells from our hotel room.","vi":"Chúng tôi có thể nghe thấy tiếng chuông nhà thờ từ phòng khách sạn."}]', '[{"phrase":"church bells"},{"phrase":"go to church"},{"phrase":"local church"}]', NULL, '/tʃɜːrtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chu/churc/church__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 11, 'machine', 'máy, máy móc', 'noun', '[{"en":"Our washing machine is broken, so I washed my clothes by hand.","vi":"Máy giặt nhà tôi bị hỏng nên tôi phải giặt quần áo bằng tay."},{"en":"You can buy a drink from the machine in the hall.","vi":"Bạn có thể mua đồ uống từ cái máy ở hành lang."},{"en":"Many factory jobs are now done by machines.","vi":"Nhiều công việc trong nhà máy giờ đây được làm bằng máy móc."}]', '[{"phrase":"washing machine"},{"phrase":"coffee machine"},{"phrase":"operate a machine"}]', NULL, '/məˈʃiːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mac/machi/machine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 12, 'achieve', 'đạt được', 'verb', '[{"en":"She worked hard to achieve her goal of becoming a doctor.","vi":"Cô ấy đã làm việc chăm chỉ để đạt được mục tiêu trở thành bác sĩ."},{"en":"Our team achieved great results this year.","vi":"Năm nay đội chúng tôi đã đạt được kết quả rất tốt."},{"en":"You can achieve a lot if you believe in yourself.","vi":"Bạn có thể đạt được nhiều điều nếu tin vào bản thân."}]', '[{"phrase":"achieve a goal"},{"phrase":"achieve success"},{"phrase":"achieve results"}]', NULL, '/əˈtʃiːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ach/achie/achieve__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 13, 'item', 'món đồ; mục, khoản', 'noun', '[{"en":"Please check each item on the list before you leave.","vi":"Vui lòng kiểm tra từng mục trong danh sách trước khi rời đi."},{"en":"The store gives a discount if you buy more than three items.","vi":"Cửa hàng giảm giá nếu bạn mua hơn ba món."},{"en":"Many household items can be recycled instead of thrown away.","vi":"Nhiều đồ gia dụng có thể được tái chế thay vì vứt đi."}]', '[{"phrase":"household items"},{"phrase":"item on the list"},{"phrase":"personal items"}]', NULL, '/ˈaɪtəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ite/item_/item__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 14, 'prove', 'chứng minh; hóa ra (là)', 'verb', '[{"en":"Can you prove that you were at home last night?","vi":"Bạn có thể chứng minh tối qua bạn ở nhà không?"},{"en":"Scientists have proved that the new medicine is safe.","vi":"Các nhà khoa học đã chứng minh rằng loại thuốc mới là an toàn."},{"en":"The exam proved easier than we expected.","vi":"Bài thi hóa ra dễ hơn chúng tôi nghĩ."}]', '[{"phrase":"prove that"},{"phrase":"prove someone wrong"},{"phrase":"prove useful"}]', 'prove – proved – proved/proven', '/pruːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prove/prove__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 15, 'cent', 'xu (đồng cent)', 'noun', '[{"en":"This pen costs ninety cents at the corner shop.","vi":"Cây bút này giá chín mươi xu ở cửa hàng đầu phố."},{"en":"She saved every cent she earned from her summer job.","vi":"Cô ấy để dành từng xu kiếm được từ công việc làm thêm mùa hè."},{"en":"Bus fares went up by fifty cents this month.","vi":"Tháng này giá vé xe buýt đã tăng năm mươi xu."}]', '[{"phrase":"every cent"},{"phrase":"a few cents"},{"phrase":"per cent"}]', '100 cent = 1 đô la hoặc 1 euro', '/sent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/cent_/cent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 16, 'season', 'mùa', 'noun', '[{"en":"Summer is the busiest season for hotels near the beach.","vi":"Mùa hè là mùa đông khách nhất của các khách sạn gần biển."},{"en":"The rainy season in the south usually starts in May.","vi":"Mùa mưa ở miền Nam thường bắt đầu vào tháng Năm."},{"en":"Which season do you like best, spring or autumn?","vi":"Bạn thích mùa nào nhất, mùa xuân hay mùa thu?"}]', '[{"phrase":"rainy season"},{"phrase":"dry season"},{"phrase":"holiday season"}]', NULL, '/ˈsiːzn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/seaso/season__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 17, 'floor', 'sàn nhà; tầng', 'noun', '[{"en":"The kids are playing with toys on the kitchen floor.","vi":"Bọn trẻ đang chơi đồ chơi trên sàn bếp."},{"en":"Our apartment is on the fifth floor of the building.","vi":"Căn hộ của chúng tôi ở tầng năm của tòa nhà."},{"en":"Be careful, the floor is still wet.","vi":"Cẩn thận, sàn nhà vẫn còn ướt."}]', '[{"phrase":"on the floor"},{"phrase":"ground floor"},{"phrase":"wooden floor"}]', 'Anh: ground floor · Mỹ: first floor (tầng trệt)', '/flɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/floor/floor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 18, 'stuff', 'đồ, đồ đạc; thứ, việc', 'noun', '[{"en":"You can leave your stuff in my car while we eat.","vi":"Bạn có thể để đồ đạc trong xe tôi trong lúc chúng ta ăn."},{"en":"I have a lot of stuff to do before the trip.","vi":"Tôi có rất nhiều việc phải làm trước chuyến đi."},{"en":"What is this sticky stuff on the table?","vi":"Cái thứ dính dính trên bàn này là gì vậy?"}]', '[{"phrase":"a lot of stuff"},{"phrase":"pack your stuff"},{"phrase":"that kind of stuff"}]', 'không đếm được; thường dùng trong văn nói', '/stʌf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/stuff/stuff__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 19, 'wide', 'rộng; nhiều, đa dạng', 'adjective', '[{"en":"The river is too wide to swim across.","vi":"Con sông quá rộng để bơi qua."},{"en":"The shop sells a wide range of fresh fruit.","vi":"Cửa hàng bán rất nhiều loại trái cây tươi."},{"en":"The road is only three meters wide.","vi":"Con đường chỉ rộng ba mét."}]', '[{"phrase":"a wide range of"},{"phrase":"a wide variety of"},{"phrase":"wide open"}]', NULL, '/waɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wid/wide_/wide__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 20, 'anyone', 'bất cứ ai; ai (đó)', 'pronoun', '[{"en":"Is anyone else coming to dinner tonight?","vi":"Tối nay còn ai khác đến ăn tối không?"},{"en":"Please don''t tell anyone about the surprise party.","vi":"Làm ơn đừng kể với ai về bữa tiệc bất ngờ nhé."},{"en":"Anyone can join the club, even complete beginners.","vi":"Bất cứ ai cũng có thể tham gia câu lạc bộ, kể cả người mới hoàn toàn."}]', '[{"phrase":"anyone else"},{"phrase":"if anyone"},{"phrase":"hardly anyone"}]', NULL, '/ˈeniwʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anyon/anyone__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 21, 'method', 'phương pháp, cách', 'noun', '[{"en":"Our teacher uses a fun method to teach grammar.","vi":"Giáo viên của chúng tôi dùng một phương pháp thú vị để dạy ngữ pháp."},{"en":"What payment methods does this shop accept?","vi":"Cửa hàng này chấp nhận những phương thức thanh toán nào?"},{"en":"Scientists tested a new method for cleaning water.","vi":"Các nhà khoa học đã thử nghiệm một phương pháp mới để làm sạch nước."}]', '[{"phrase":"teaching method"},{"phrase":"payment method"},{"phrase":"new method"}]', NULL, '/ˈmeθəd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/metho/method__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 22, 'analysis', 'sự phân tích; bản phân tích', 'noun', '[{"en":"The doctor sent a blood sample to the lab for analysis.","vi":"Bác sĩ gửi mẫu máu đến phòng xét nghiệm để phân tích."},{"en":"Her analysis of the sales data was clear and useful.","vi":"Bản phân tích dữ liệu bán hàng của cô ấy rõ ràng và hữu ích."},{"en":"After careful analysis, we decided to change our plan.","vi":"Sau khi phân tích kỹ lưỡng, chúng tôi quyết định thay đổi kế hoạch."}]', '[{"phrase":"careful analysis"},{"phrase":"data analysis"},{"phrase":"analysis of"}]', 'số nhiều: analyses', '/əˈnæləsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analy/analysis__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 23, 'election', 'cuộc bầu cử', 'noun', '[{"en":"The next election will be held in two years.","vi":"Cuộc bầu cử tiếp theo sẽ được tổ chức sau hai năm nữa."},{"en":"Our class held an election to choose a new class leader.","vi":"Lớp chúng tôi đã tổ chức bầu cử để chọn lớp trưởng mới."},{"en":"Young people should vote in local elections.","vi":"Người trẻ nên đi bỏ phiếu trong các cuộc bầu cử địa phương."}]', '[{"phrase":"hold an election"},{"phrase":"win an election"},{"phrase":"local election"}]', NULL, '/ɪˈlekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/election__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 24, 'military', '(thuộc) quân sự, quân đội', 'adjective', '[{"en":"My grandfather did two years of military service.","vi":"Ông tôi đã đi nghĩa vụ quân sự hai năm."},{"en":"The old military base is now a public park.","vi":"Căn cứ quân sự cũ nay đã trở thành công viên công cộng."},{"en":"Military planes flew over the city during the celebration.","vi":"Máy bay quân sự bay qua thành phố trong buổi lễ kỷ niệm."}]', '[{"phrase":"military service"},{"phrase":"military base"},{"phrase":"military training"}]', NULL, '/ˈmɪləteri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/milit/military__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 25, 'hotel', 'khách sạn', 'noun', '[{"en":"We stayed at a small hotel near the beach.","vi":"Chúng tôi ở một khách sạn nhỏ gần biển."},{"en":"I booked a hotel room for two nights.","vi":"Tôi đã đặt một phòng khách sạn cho hai đêm."},{"en":"Is breakfast included in the price of the hotel?","vi":"Giá khách sạn có bao gồm bữa sáng không?"}]', '[{"phrase":"stay at a hotel"},{"phrase":"hotel room"},{"phrase":"book a hotel"}]', NULL, '/həʊˈtel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hot/hotel/hotel__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 26, 'club', 'câu lạc bộ; hộp đêm', 'noun', '[{"en":"My son joined the school chess club this year.","vi":"Năm nay con trai tôi đã tham gia câu lạc bộ cờ vua của trường."},{"en":"The book club meets every Thursday evening at the library.","vi":"Câu lạc bộ sách họp vào tối thứ Năm hằng tuần ở thư viện."},{"en":"After dinner, they went dancing at a club downtown.","vi":"Sau bữa tối, họ đi nhảy ở một hộp đêm trong trung tâm thành phố."}]', '[{"phrase":"join a club"},{"phrase":"book club"},{"phrase":"football club"}]', NULL, '/klʌb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clu/club_/club__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 27, 'below', 'dưới, bên dưới', 'preposition', '[{"en":"The temperature dropped below zero last night.","vi":"Đêm qua nhiệt độ đã xuống dưới 0 độ."},{"en":"His grades were below average this term.","vi":"Học kỳ này điểm của cậu ấy dưới mức trung bình."},{"en":"Please write your name in the box below.","vi":"Vui lòng viết tên bạn vào ô bên dưới."}]', '[{"phrase":"below zero"},{"phrase":"below average"},{"phrase":"see below"}]', NULL, '/bɪˈləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/below/below__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 28, 'movie', 'bộ phim', 'noun', '[{"en":"Do you want to watch a movie tonight?","vi":"Tối nay bạn có muốn xem phim không?"},{"en":"We went to the movies after dinner on Saturday.","vi":"Thứ Bảy chúng tôi đi xem phim sau bữa tối."},{"en":"That movie was so boring that I fell asleep.","vi":"Bộ phim đó chán đến mức tôi ngủ quên."}]', '[{"phrase":"watch a movie"},{"phrase":"go to the movies"},{"phrase":"movie theater"}]', 'Mỹ: movie · Anh: film', '/ˈmuːvi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mov/movie/movie__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-09', 29, 'doctor', 'bác sĩ', 'noun', '[{"en":"You should see a doctor if the pain gets worse.","vi":"Bạn nên đi khám bác sĩ nếu cơn đau nặng hơn."},{"en":"My aunt works as a doctor at the city hospital.","vi":"Dì tôi làm bác sĩ ở bệnh viện thành phố."},{"en":"The doctor told me to rest for a few days.","vi":"Bác sĩ bảo tôi nghỉ ngơi vài ngày."}]', '[{"phrase":"see a doctor"},{"phrase":"go to the doctor"},{"phrase":"family doctor"}]', NULL, '/ˈdɑːktər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doc/docto/doctor__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-10', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 10', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 10);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 1, 'discussion', 'cuộc thảo luận; sự bàn bạc', 'noun', '[{"en":"We had a long discussion about where to go on vacation.","vi":"Chúng tôi đã thảo luận rất lâu về việc đi nghỉ ở đâu."},{"en":"After much discussion, they finally agreed on a name for the baby.","vi":"Sau nhiều lần bàn bạc, cuối cùng họ cũng thống nhất được tên cho em bé."},{"en":"Our teacher started a class discussion about staying safe online.","vi":"Cô giáo bắt đầu một buổi thảo luận trên lớp về cách giữ an toàn trên mạng."}]', '[{"phrase":"have a discussion"},{"phrase":"group discussion"},{"phrase":"under discussion"},{"phrase":"discussion about"}]', NULL, '/dɪˈskʌʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discu/discussion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 2, 'sorry', 'xin lỗi; lấy làm tiếc; thấy thương', 'adjective', '[{"en":"I''m sorry I forgot to call you last night.","vi":"Xin lỗi, tối qua tôi quên gọi cho bạn."},{"en":"We were sorry to hear that your grandfather is ill.","vi":"Chúng tôi rất tiếc khi nghe tin ông của bạn bị ốm."},{"en":"I felt sorry for the little boy who lost his dog.","vi":"Tôi thấy thương cậu bé bị lạc mất con chó."}]', '[{"phrase":"say sorry"},{"phrase":"sorry to hear"},{"phrase":"feel sorry for"},{"phrase":"sorry about"}]', 'feel sorry for sb: thấy thương ai', '/ˈsɑːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sor/sorry/sorry__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 3, 'challenge', 'thử thách; thách thức', 'noun', '[{"en":"Learning a new language is a big challenge for adults.","vi":"Học một ngôn ngữ mới là một thử thách lớn đối với người lớn."},{"en":"She enjoys the challenge of running her own small business.","vi":"Cô ấy thích thử thách của việc tự điều hành doanh nghiệp nhỏ của mình."},{"en":"Our company is facing many new challenges this year.","vi":"Năm nay công ty chúng tôi đang phải đối mặt với nhiều thách thức mới."}]', '[{"phrase":"face a challenge"},{"phrase":"big challenge"},{"phrase":"meet a challenge"},{"phrase":"rise to the challenge"}]', NULL, '/ˈtʃælɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chall/challenge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 4, 'nation', 'quốc gia; dân tộc', 'noun', '[{"en":"The whole nation watched the final match on TV.","vi":"Cả nước đã theo dõi trận chung kết trên TV."},{"en":"Athletes from over fifty nations took part in the competition.","vi":"Vận động viên từ hơn năm mươi quốc gia đã tham gia cuộc thi đấu."},{"en":"It is one of the richest nations in the world.","vi":"Đó là một trong những quốc gia giàu nhất thế giới."}]', '[{"phrase":"the whole nation"},{"phrase":"developing nations"},{"phrase":"wealthy nations"}]', NULL, '/ˈneɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natio/nation__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 5, 'nearly', 'gần như; suýt', 'adverb', '[{"en":"It''s nearly ten o''clock, so we should go to bed.","vi":"Gần mười giờ rồi, chúng ta nên đi ngủ thôi."},{"en":"I nearly missed the bus this morning.","vi":"Sáng nay tôi suýt lỡ chuyến xe buýt."},{"en":"Nearly all of my classmates passed the final exam.","vi":"Gần như tất cả bạn cùng lớp của tôi đều đậu kỳ thi cuối kỳ."}]', '[{"phrase":"nearly all"},{"phrase":"nearly always"},{"phrase":"nearly finished"},{"phrase":"nearly every"}]', NULL, '/ˈnɪrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nea/nearl/nearly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 6, 'statement', 'lời tuyên bố, thông báo; lời khai; bản sao kê', 'noun', '[{"en":"The company made a statement about the delay on its website.","vi":"Công ty đã đưa ra thông báo về việc chậm trễ trên trang web của mình."},{"en":"The police took a statement from the driver after the accident.","vi":"Cảnh sát đã lấy lời khai của tài xế sau vụ tai nạn."},{"en":"Check your bank statement carefully at the end of each month.","vi":"Hãy kiểm tra kỹ bản sao kê ngân hàng vào cuối mỗi tháng."}]', '[{"phrase":"make a statement"},{"phrase":"issue a statement"},{"phrase":"official statement"},{"phrase":"bank statement"}]', NULL, '/ˈsteɪtmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/state/statement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 7, 'link', 'mối liên hệ; đường liên kết (link); tuyến nối', 'noun', '[{"en":"Scientists have found a link between sleep and memory.","vi":"Các nhà khoa học đã tìm ra mối liên hệ giữa giấc ngủ và trí nhớ."},{"en":"Click the link in the email to reset your password.","vi":"Hãy bấm vào đường link trong email để đặt lại mật khẩu."},{"en":"The new bridge is an important link between the two towns.","vi":"Cây cầu mới là tuyến nối quan trọng giữa hai thị trấn."}]', '[{"phrase":"link between"},{"phrase":"close link"},{"phrase":"click on a link"},{"phrase":"strong link"}]', NULL, '/lɪŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lin/link_/link__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 8, 'despite', 'mặc dù; bất chấp', 'preposition', '[{"en":"We still went for a walk despite the rain.","vi":"Chúng tôi vẫn đi dạo mặc dù trời mưa."},{"en":"Despite being tired, she stayed up to finish her homework.","vi":"Dù mệt, cô ấy vẫn thức để làm xong bài tập về nhà."},{"en":"The team lost the game despite playing very well.","vi":"Đội đã thua trận dù chơi rất hay."}]', '[{"phrase":"despite the fact that"},{"phrase":"despite this"},{"phrase":"despite the rain"}]', 'despite + danh từ/V-ing (không dùng ''despite of'')', '/dɪˈspaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/despi/despite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 9, 'introduce', 'giới thiệu; đưa vào áp dụng', 'verb', '[{"en":"Let me introduce you to my parents.","vi":"Để tôi giới thiệu bạn với bố mẹ tôi."},{"en":"She stood up and introduced herself to the class.","vi":"Cô ấy đứng dậy và tự giới thiệu với cả lớp."},{"en":"The school introduced a new rule about mobile phones last year.","vi":"Năm ngoái trường đã áp dụng một quy định mới về điện thoại di động."}]', '[{"phrase":"introduce yourself"},{"phrase":"introduce someone to"},{"phrase":"introduce a new law"}]', NULL, '/ˌɪntrəˈduːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intro/introduce__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 10, 'advantage', 'lợi thế; ưu điểm', 'noun', '[{"en":"One advantage of living in the city is good public transportation.","vi":"Một ưu điểm của việc sống ở thành phố là giao thông công cộng tốt."},{"en":"Her height gives her a big advantage in basketball.","vi":"Chiều cao mang lại cho cô ấy lợi thế lớn trong môn bóng rổ."},{"en":"You should take advantage of the sunny weather and go outside.","vi":"Bạn nên tận dụng thời tiết nắng đẹp để ra ngoài."}]', '[{"phrase":"take advantage of"},{"phrase":"big advantage"},{"phrase":"advantages and disadvantages"},{"phrase":"an advantage over"}]', 'take advantage of: tận dụng; lợi dụng', '/ədˈvæntɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advan/advantage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 11, 'ready', 'sẵn sàng; (đã) xong', 'adjective', '[{"en":"Are you ready to order, or do you need more time?","vi":"Bạn đã sẵn sàng gọi món chưa, hay cần thêm thời gian?"},{"en":"Dinner will be ready in about ten minutes.","vi":"Khoảng mười phút nữa bữa tối sẽ xong."},{"en":"It took her an hour to get ready for the party.","vi":"Cô ấy mất một tiếng để chuẩn bị đi dự tiệc."}]', '[{"phrase":"get ready"},{"phrase":"ready to go"},{"phrase":"ready for"}]', NULL, '/ˈredi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/ready/ready__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 12, 'marry', 'cưới; kết hôn (với)', 'verb', '[{"en":"My sister is going to marry her boyfriend next spring.","vi":"Chị tôi sẽ cưới bạn trai vào mùa xuân tới."},{"en":"They got married on a beach in the summer.","vi":"Họ kết hôn trên một bãi biển vào mùa hè."},{"en":"My grandparents married young and have been together for sixty years.","vi":"Ông bà tôi cưới nhau từ khi còn trẻ và đã bên nhau sáu mươi năm."}]', '[{"phrase":"get married"},{"phrase":"marry someone"},{"phrase":"be married to"}]', 'marry sb (không dùng ''marry with sb'')', '/ˈmæri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/marry/marry__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 13, 'strike', 'đánh, đập vào; (sét) đánh; đình công', 'verb', '[{"en":"The house was struck by lightning during the storm.","vi":"Ngôi nhà bị sét đánh trong cơn bão."},{"en":"The ball struck him on the head, but he was fine.","vi":"Quả bóng đập vào đầu anh ấy, nhưng anh ấy không sao."},{"en":"Workers at the factory are striking for better pay.","vi":"Công nhân ở nhà máy đang đình công đòi tăng lương."}]', '[{"phrase":"go on strike"},{"phrase":"lightning strikes"},{"phrase":"strike a match"},{"phrase":"strike a balance"}]', 'strike – struck – struck', '/straɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strik/strike__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 14, 'mile', 'dặm (≈ 1,6 km)', 'noun', '[{"en":"My office is about two miles from my house.","vi":"Văn phòng tôi cách nhà khoảng hai dặm."},{"en":"We drove for miles without seeing a single gas station.","vi":"Chúng tôi lái xe hàng dặm mà không thấy một trạm xăng nào."},{"en":"She runs five miles every morning before work.","vi":"Mỗi sáng cô ấy chạy năm dặm trước khi đi làm."}]', '[{"phrase":"miles away"},{"phrase":"for miles"},{"phrase":"miles per hour"},{"phrase":"a mile from"}]', '1 dặm ≈ 1,6 km', '/maɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/mile_/mile__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 15, 'seek', 'tìm kiếm; xin (lời khuyên, sự giúp đỡ)', 'verb', '[{"en":"Many young people move to the city to seek work.","vi":"Nhiều người trẻ chuyển lên thành phố để tìm việc làm."},{"en":"You should seek advice from a doctor before starting the diet.","vi":"Bạn nên xin lời khuyên của bác sĩ trước khi bắt đầu chế độ ăn kiêng."},{"en":"The family sought help from their neighbors after the flood.","vi":"Sau trận lũ, gia đình ấy đã tìm đến sự giúp đỡ của hàng xóm."}]', '[{"phrase":"seek help"},{"phrase":"seek advice"},{"phrase":"seek work"},{"phrase":"seek to do"}]', 'seek – sought – sought', '/siːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seek_/seek__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 16, 'ability', 'khả năng; năng lực', 'noun', '[{"en":"She has the ability to explain difficult ideas simply.","vi":"Cô ấy có khả năng giải thích những ý tưởng khó một cách đơn giản."},{"en":"Students of all abilities are welcome to join the art club.","vi":"Học sinh ở mọi trình độ đều được chào đón tham gia câu lạc bộ mỹ thuật."},{"en":"Stress can affect your ability to sleep well.","vi":"Căng thẳng có thể ảnh hưởng đến khả năng ngủ ngon của bạn."}]', '[{"phrase":"have the ability to"},{"phrase":"natural ability"},{"phrase":"of all abilities"}]', NULL, '/əˈbɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abi/abili/ability__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 17, 'unit', 'đơn vị; bài (trong sách); khoa, bộ phận', 'noun', '[{"en":"A meter is a common unit for measuring length.","vi":"Mét là một đơn vị thông dụng để đo chiều dài."},{"en":"We will finish Unit 5 of the textbook next week.","vi":"Tuần sau chúng ta sẽ học xong Bài 5 trong sách giáo khoa."},{"en":"My uncle works in the hospital''s intensive care unit.","vi":"Chú tôi làm việc ở khoa hồi sức tích cực của bệnh viện."}]', '[{"phrase":"unit of measurement"},{"phrase":"intensive care unit"},{"phrase":"family unit"}]', NULL, '/ˈjuːnɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unit_/unit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 18, 'card', 'thẻ; tấm thiếp; lá bài', 'noun', '[{"en":"Can I pay by card, or do you only take cash?","vi":"Tôi trả bằng thẻ được không, hay ở đây chỉ nhận tiền mặt?"},{"en":"We sent my grandmother a birthday card with a family photo.","vi":"Chúng tôi gửi bà một tấm thiếp sinh nhật kèm ảnh gia đình."},{"en":"My friends and I often play cards on rainy evenings.","vi":"Tôi và bạn bè thường chơi bài vào những buổi tối mưa."}]', '[{"phrase":"credit card"},{"phrase":"birthday card"},{"phrase":"play cards"},{"phrase":"pay by card"}]', NULL, '/kɑːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/card_/card__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 19, 'hospital', 'bệnh viện', 'noun', '[{"en":"My mother works as a nurse at the local hospital.","vi":"Mẹ tôi làm y tá ở bệnh viện địa phương."},{"en":"He had to stay in the hospital for three days.","vi":"Anh ấy phải nằm viện ba ngày."},{"en":"We visited my uncle in the hospital after his surgery.","vi":"Chúng tôi vào bệnh viện thăm chú tôi sau ca phẫu thuật."}]', '[{"phrase":"in the hospital"},{"phrase":"go to the hospital"},{"phrase":"leave the hospital"},{"phrase":"hospital bed"}]', 'Anh: in hospital · Mỹ: in the hospital', '/ˈhɑːspɪtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hos/hospi/hospital__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 20, 'quickly', 'nhanh; nhanh chóng', 'adverb', '[{"en":"She quickly finished her breakfast and ran to school.","vi":"Cô ấy nhanh chóng ăn xong bữa sáng rồi chạy đến trường."},{"en":"Young children usually learn new languages very quickly.","vi":"Trẻ nhỏ thường học ngôn ngữ mới rất nhanh."},{"en":"The news spread quickly through the small village.","vi":"Tin tức lan nhanh khắp ngôi làng nhỏ."}]', '[{"phrase":"very quickly"},{"phrase":"act quickly"},{"phrase":"spread quickly"},{"phrase":"move quickly"}]', NULL, '/ˈkwɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quick/quickly__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 21, 'interview', 'cuộc phỏng vấn', 'noun', '[{"en":"I have a job interview at a bank tomorrow morning.","vi":"Sáng mai tôi có buổi phỏng vấn xin việc ở một ngân hàng."},{"en":"She wore her best suit to the interview.","vi":"Cô ấy mặc bộ vest đẹp nhất đến buổi phỏng vấn."},{"en":"The singer gave an interview to a local newspaper.","vi":"Ca sĩ đó đã trả lời phỏng vấn cho một tờ báo địa phương."}]', '[{"phrase":"job interview"},{"phrase":"give an interview"},{"phrase":"have an interview"},{"phrase":"interview with"}]', NULL, '/ˈɪntərvjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interview__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 22, 'agreement', 'sự đồng ý; thỏa thuận; hợp đồng', 'noun', '[{"en":"After a long talk, we finally reached an agreement.","vi":"Sau một cuộc nói chuyện dài, cuối cùng chúng tôi cũng đạt được thỏa thuận."},{"en":"Please read the rental agreement carefully before you sign it.","vi":"Hãy đọc kỹ hợp đồng thuê nhà trước khi ký."},{"en":"Everyone in the room nodded in agreement.","vi":"Mọi người trong phòng đều gật đầu đồng ý."}]', '[{"phrase":"reach an agreement"},{"phrase":"sign an agreement"},{"phrase":"in agreement"},{"phrase":"come to an agreement"}]', NULL, '/əˈɡriːmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agr/agree/agreement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 23, 'release', 'phát hành, ra mắt; thả ra; thải ra', 'verb', '[{"en":"The band will release their new album next month.","vi":"Ban nhạc sẽ phát hành album mới vào tháng tới."},{"en":"We released the bird after its wing had healed.","vi":"Chúng tôi thả con chim đi sau khi cánh của nó đã lành."},{"en":"The factory was fined for releasing dirty water into the river.","vi":"Nhà máy bị phạt vì xả nước bẩn ra sông."}]', '[{"phrase":"release an album"},{"phrase":"release a statement"},{"phrase":"release a report"}]', NULL, '/rɪˈliːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relea/release__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 24, 'tax', 'thuế', 'noun', '[{"en":"Prices in this store do not include tax.","vi":"Giá trong cửa hàng này chưa bao gồm thuế."},{"en":"How much tax do you pay on your salary?","vi":"Lương của bạn phải đóng bao nhiêu tiền thuế?"},{"en":"Many people think the new tax on sugary drinks is a good idea.","vi":"Nhiều người cho rằng thuế mới đánh vào đồ uống có đường là một ý hay."}]', '[{"phrase":"pay tax"},{"phrase":"income tax"},{"phrase":"tax on"},{"phrase":"raise taxes"}]', NULL, '/tæks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tax/tax__/tax__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 25, 'solution', 'giải pháp; lời giải', 'noun', '[{"en":"We need to find a solution to the parking problem.","vi":"Chúng ta cần tìm ra giải pháp cho vấn đề đỗ xe."},{"en":"The solutions to the exercises are at the back of the book.","vi":"Lời giải của các bài tập nằm ở cuối sách."},{"en":"There is no easy solution to this problem.","vi":"Không có giải pháp dễ dàng nào cho vấn đề này."}]', '[{"phrase":"find a solution"},{"phrase":"solution to"},{"phrase":"simple solution"},{"phrase":"possible solution"}]', NULL, '/səˈluːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solut/solution__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 26, 'capital', 'thủ đô; vốn; chữ viết hoa', 'noun', '[{"en":"Hanoi is the capital and the second largest city of Vietnam.","vi":"Hà Nội là thủ đô và là thành phố lớn thứ hai của Việt Nam."},{"en":"They need more capital to open a second restaurant.","vi":"Họ cần thêm vốn để mở nhà hàng thứ hai."},{"en":"Always start a sentence with a capital letter.","vi":"Luôn bắt đầu câu bằng chữ viết hoa."}]', '[{"phrase":"capital city"},{"phrase":"the capital of"},{"phrase":"capital letter"},{"phrase":"raise capital"}]', NULL, '/ˈkæpɪtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capit/capital__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 27, 'popular', 'phổ biến; được ưa chuộng, được yêu thích', 'adjective', '[{"en":"Soccer is the most popular sport in my country.","vi":"Bóng đá là môn thể thao phổ biến nhất ở nước tôi."},{"en":"This beach is very popular with tourists in the summer.","vi":"Bãi biển này rất được khách du lịch ưa chuộng vào mùa hè."},{"en":"He was one of the most popular teachers at our school.","vi":"Thầy ấy là một trong những giáo viên được yêu thích nhất trường tôi."}]', '[{"phrase":"popular with"},{"phrase":"very popular"},{"phrase":"most popular"},{"phrase":"popular music"}]', NULL, '/ˈpɑːpjələr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pop/popul/popular__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 28, 'specific', 'cụ thể; riêng, nhất định', 'adjective', '[{"en":"Can you give me a specific example?","vi":"Bạn có thể cho tôi một ví dụ cụ thể không?"},{"en":"The doctor gave me specific instructions about taking the medicine.","vi":"Bác sĩ đã hướng dẫn cụ thể cho tôi về cách uống thuốc."},{"en":"Each room in the house is designed for a specific purpose.","vi":"Mỗi phòng trong ngôi nhà được thiết kế cho một mục đích riêng."}]', '[{"phrase":"specific example"},{"phrase":"specific purpose"},{"phrase":"specific instructions"},{"phrase":"be more specific"}]', NULL, '/spəˈsɪfɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specific__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-10', 29, 'beautiful', 'đẹp; tuyệt vời', 'adjective', '[{"en":"What a beautiful view of the mountains from here!","vi":"Từ đây nhìn ra núi, cảnh đẹp quá!"},{"en":"She wore a beautiful red dress to the wedding.","vi":"Cô ấy mặc một chiếc váy đỏ rất đẹp đến dự đám cưới."},{"en":"We had a beautiful day for our picnic by the lake.","vi":"Chúng tôi có một ngày đẹp trời cho buổi dã ngoại bên hồ."}]', '[{"phrase":"beautiful view"},{"phrase":"beautiful day"},{"phrase":"absolutely beautiful"},{"phrase":"beautiful woman"}]', NULL, '/ˈbjuːtɪfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beaut/beautiful__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-11', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 11', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 11);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 1, 'fear', 'nỗi sợ; sự lo sợ', 'noun', '[{"en":"Many young children have a fear of the dark.","vi":"Nhiều trẻ nhỏ sợ bóng tối."},{"en":"She finally overcame her fear of flying last year.","vi":"Năm ngoái, cuối cùng cô ấy đã vượt qua nỗi sợ đi máy bay."},{"en":"There is growing fear that prices will rise again.","vi":"Ngày càng có nhiều lo sợ rằng giá cả sẽ lại tăng."}]', '[{"phrase":"fear of"},{"phrase":"overcome a fear"},{"phrase":"live in fear"}]', NULL, '/fɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fea/fear_/fear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 2, 'aim', 'mục tiêu; mục đích', 'noun', '[{"en":"Our main aim is to finish the project by June.","vi":"Mục tiêu chính của chúng tôi là hoàn thành dự án trước tháng Sáu."},{"en":"The aim of this course is to improve your speaking skills.","vi":"Mục đích của khóa học này là cải thiện kỹ năng nói của bạn."},{"en":"She moved to the city with the aim of finding a better job.","vi":"Cô ấy chuyển lên thành phố với mục đích tìm một công việc tốt hơn."}]', '[{"phrase":"main aim"},{"phrase":"the aim of"},{"phrase":"with the aim of"},{"phrase":"achieve an aim"}]', 'aim (v) = nhắm tới: aim to do something', '/eɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aim/aim__/aim__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 3, 'television', 'tivi; truyền hình', 'noun', '[{"en":"We watched an old movie on television last night.","vi":"Tối qua chúng tôi xem một bộ phim cũ trên tivi."},{"en":"My grandparents bought a new television for the living room.","vi":"Ông bà tôi đã mua một chiếc tivi mới cho phòng khách."},{"en":"She has worked in television as a news reporter for years.","vi":"Cô ấy đã làm phóng viên tin tức trong ngành truyền hình nhiều năm."}]', '[{"phrase":"watch television"},{"phrase":"on television"},{"phrase":"television show"},{"phrase":"turn on the television"}]', NULL, '/ˈtelɪvɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tel/telev/television__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 4, 'serious', 'nghiêm trọng; nghiêm túc', 'adjective', '[{"en":"Pollution is a serious problem in many big cities.","vi":"Ô nhiễm là một vấn đề nghiêm trọng ở nhiều thành phố lớn."},{"en":"He suffered a serious injury while playing football.","vi":"Anh ấy bị chấn thương nghiêm trọng khi chơi bóng đá."},{"en":"Are you serious about quitting your job next month?","vi":"Bạn nghiêm túc về chuyện nghỉ việc vào tháng sau à?"}]', '[{"phrase":"serious problem"},{"phrase":"serious injury"},{"phrase":"be serious about"}]', NULL, '/ˈsɪriəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serio/serious__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 5, 'target', 'mục tiêu; chỉ tiêu', 'noun', '[{"en":"The company met its sales target two months early.","vi":"Công ty đã đạt chỉ tiêu doanh số sớm hai tháng."},{"en":"We set a target of saving 500 dollars every month.","vi":"Chúng tôi đặt mục tiêu tiết kiệm 500 đô la mỗi tháng."},{"en":"He threw the ball hard but missed the target completely.","vi":"Anh ấy ném bóng thật mạnh nhưng trượt mục tiêu hoàn toàn."}]', '[{"phrase":"sales target"},{"phrase":"set a target"},{"phrase":"meet a target"},{"phrase":"hit the target"}]', NULL, '/ˈtɑːrɡɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tar/targe/target__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 6, 'degree', 'độ; bằng (đại học); mức độ', 'noun', '[{"en":"It was over 35 degrees outside this afternoon.","vi":"Chiều nay ngoài trời hơn 35 độ."},{"en":"She has a degree in computer science from a good university.","vi":"Cô ấy có bằng ngành khoa học máy tính của một trường đại học tốt."},{"en":"I agree with what you said to some degree.","vi":"Ở một mức độ nào đó, tôi đồng ý với những gì bạn nói."}]', '[{"phrase":"a degree in"},{"phrase":"university degree"},{"phrase":"to some degree"},{"phrase":"degrees Celsius"}]', NULL, '/dɪˈɡriː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deg/degre/degree__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 7, 'pull', 'kéo; nhổ', 'verb', '[{"en":"You need to pull hard because the door sometimes gets stuck.","vi":"Bạn cần kéo mạnh vì cửa đôi khi bị kẹt."},{"en":"My little sister pulled my arm and asked me to play.","vi":"Em gái tôi kéo tay tôi và rủ tôi chơi."},{"en":"I had a tooth pulled at the dentist yesterday.","vi":"Hôm qua tôi đi nha sĩ nhổ một chiếc răng."}]', '[{"phrase":"pull hard"},{"phrase":"pull out"},{"phrase":"pull over"}]', NULL, '/pʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pul/pull_/pull__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 8, 'red', 'đỏ', 'adjective', '[{"en":"She wore a long red dress to the party.","vi":"Cô ấy mặc một chiếc váy dài màu đỏ đến bữa tiệc."},{"en":"Stop the car when the traffic light turns red.","vi":"Hãy dừng xe khi đèn giao thông chuyển sang đỏ."},{"en":"His face went red when everyone started laughing at him.","vi":"Mặt anh ấy đỏ bừng khi mọi người bắt đầu cười anh ấy."}]', '[{"phrase":"turn red"},{"phrase":"go red"},{"phrase":"bright red"},{"phrase":"red wine"}]', NULL, '/red/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/red/red__/red__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 9, 'husband', 'chồng', 'noun', '[{"en":"Her husband works as a teacher at a local school.","vi":"Chồng cô ấy làm giáo viên ở một trường học địa phương."},{"en":"My husband and I met at university.","vi":"Tôi và chồng quen nhau ở trường đại học."},{"en":"She called her husband to say she would be late.","vi":"Cô ấy gọi cho chồng để báo rằng mình sẽ về muộn."}]', '[{"phrase":"husband and wife"},{"phrase":"my husband and I"},{"phrase":"ex-husband"}]', NULL, '/ˈhʌzbənd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hus/husba/husband__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 10, 'access', 'quyền truy cập; sự tiếp cận', 'noun', '[{"en":"Students have free access to the library''s online books.","vi":"Sinh viên được truy cập miễn phí vào sách trực tuyến của thư viện."},{"en":"Many villages still have no access to clean water.","vi":"Nhiều ngôi làng vẫn chưa được tiếp cận với nước sạch."},{"en":"You need a password to get access to the system.","vi":"Bạn cần mật khẩu để truy cập vào hệ thống."}]', '[{"phrase":"access to"},{"phrase":"have access to"},{"phrase":"internet access"},{"phrase":"free access"}]', 'access to + danh từ; access (v) không có "to": access the website', '/ˈækses/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/acces/access__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 11, 'movement', 'chuyển động; cử động; phong trào', 'noun', '[{"en":"She noticed a slight movement in the bushes outside.","vi":"Cô ấy nhận thấy có chuyển động nhẹ trong bụi cây bên ngoài."},{"en":"The doctor told me to avoid sudden movements of my neck.","vi":"Bác sĩ dặn tôi tránh cử động cổ đột ngột."},{"en":"The movement to protect the environment is growing among young people.","vi":"Phong trào bảo vệ môi trường đang lớn mạnh trong giới trẻ."}]', '[{"phrase":"slight movement"},{"phrase":"sudden movement"},{"phrase":"environmental movement"}]', NULL, '/ˈmuːvmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mov/movem/movement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 12, 'treat', 'đối xử; chữa trị; đãi', 'verb', '[{"en":"My boss always treats everyone with respect.","vi":"Sếp tôi luôn đối xử tôn trọng với mọi người."},{"en":"The hospital treated dozens of people after the accident.","vi":"Bệnh viện đã chữa trị cho hàng chục người sau vụ tai nạn."},{"en":"Let me treat you to dinner for your birthday.","vi":"Để tôi đãi bạn bữa tối nhân dịp sinh nhật bạn nhé."}]', '[{"phrase":"treat someone with respect"},{"phrase":"treat a patient"},{"phrase":"treat someone to something"},{"phrase":"treat badly"}]', NULL, '/triːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/treat/treat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 13, 'identify', 'nhận ra; xác định', 'verb', '[{"en":"Can you identify the man in this photo?","vi":"Bạn có nhận ra người đàn ông trong bức ảnh này không?"},{"en":"Scientists have identified the cause of the disease.","vi":"Các nhà khoa học đã xác định được nguyên nhân gây ra căn bệnh."},{"en":"We need to identify the problem before we can fix it.","vi":"Chúng ta cần xác định vấn đề trước khi có thể khắc phục nó."}]', '[{"phrase":"identify the problem"},{"phrase":"identify the cause"},{"phrase":"clearly identify"}]', NULL, '/aɪˈdentɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identify__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 14, 'loss', 'sự mất; sự thua lỗ', 'noun', '[{"en":"Weight loss is not always easy after the age of forty.","vi":"Sau tuổi bốn mươi, giảm cân không phải lúc nào cũng dễ."},{"en":"The storm caused a loss of power across the whole town.","vi":"Cơn bão khiến cả thị trấn bị mất điện."},{"en":"The company reported a loss of two million dollars last year.","vi":"Năm ngoái công ty báo lỗ hai triệu đô la."}]', '[{"phrase":"weight loss"},{"phrase":"loss of power"},{"phrase":"heavy losses"},{"phrase":"report a loss"}]', NULL, '/lɔːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/los/loss_/loss__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 15, 'modern', 'hiện đại', 'adjective', '[{"en":"They live in a modern apartment near the city center.","vi":"Họ sống trong một căn hộ hiện đại gần trung tâm thành phố."},{"en":"Smartphones have become an important part of modern life.","vi":"Điện thoại thông minh đã trở thành một phần quan trọng của cuộc sống hiện đại."},{"en":"The hospital uses some of the most modern equipment in the country.","vi":"Bệnh viện sử dụng một số thiết bị hiện đại nhất cả nước."}]', '[{"phrase":"modern life"},{"phrase":"modern technology"},{"phrase":"modern art"}]', NULL, '/ˈmɑːdərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/moder/modern__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 16, 'pressure', 'áp lực; áp suất', 'noun', '[{"en":"Many students feel a lot of pressure before exams.","vi":"Nhiều học sinh cảm thấy rất áp lực trước kỳ thi."},{"en":"She stays calm and works well under pressure.","vi":"Cô ấy giữ bình tĩnh và làm việc tốt dưới áp lực."},{"en":"Check the tire pressure before you go on a long drive.","vi":"Hãy kiểm tra áp suất lốp trước khi lái xe đường dài."}]', '[{"phrase":"under pressure"},{"phrase":"blood pressure"},{"phrase":"put pressure on"},{"phrase":"tire pressure"}]', NULL, '/ˈpreʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/press/pressure__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 17, 'bus', 'xe buýt', 'noun', '[{"en":"I usually take the bus to work in the morning.","vi":"Buổi sáng tôi thường đi xe buýt đi làm."},{"en":"We missed the last bus and had to walk home.","vi":"Chúng tôi lỡ chuyến xe buýt cuối cùng và phải đi bộ về nhà."},{"en":"The bus stop is just across the street from my house.","vi":"Trạm xe buýt ở ngay bên kia đường, đối diện nhà tôi."}]', '[{"phrase":"take the bus"},{"phrase":"bus stop"},{"phrase":"miss the bus"},{"phrase":"by bus"}]', NULL, '/bʌs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bus/bus__/bus__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 18, 'treatment', 'sự điều trị; sự đối xử', 'noun', '[{"en":"He is receiving treatment for a back injury.","vi":"Anh ấy đang được điều trị chấn thương lưng."},{"en":"The new treatment helped her feel better within a week.","vi":"Phương pháp điều trị mới giúp cô ấy thấy khỏe hơn trong vòng một tuần."},{"en":"All workers should receive equal treatment, whatever their age.","vi":"Mọi người lao động đều nên được đối xử bình đẳng, bất kể tuổi tác."}]', '[{"phrase":"receive treatment"},{"phrase":"medical treatment"},{"phrase":"treatment for"},{"phrase":"equal treatment"}]', NULL, '/ˈtriːtmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/treat/treatment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 19, 'conference', 'hội nghị; hội thảo', 'noun', '[{"en":"She is going to a business conference in Tokyo next week.","vi":"Tuần sau cô ấy sẽ đi dự một hội nghị kinh doanh ở Tokyo."},{"en":"More than five hundred teachers attended the conference this year.","vi":"Năm nay có hơn năm trăm giáo viên tham dự hội thảo."},{"en":"My manager is on a conference call until three o''clock.","vi":"Quản lý của tôi đang trong một cuộc gọi hội nghị đến ba giờ."}]', '[{"phrase":"attend a conference"},{"phrase":"business conference"},{"phrase":"conference call"},{"phrase":"press conference"}]', NULL, '/ˈkɑːnfərəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconference__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 20, 'supply', 'nguồn cung; đồ dùng, vật tư', 'noun', '[{"en":"The city has a limited supply of fresh water in summer.","vi":"Vào mùa hè, thành phố có nguồn cung nước sạch hạn chế."},{"en":"We need to buy more office supplies before Monday.","vi":"Chúng ta cần mua thêm văn phòng phẩm trước thứ Hai."},{"en":"Fresh vegetables are in short supply during the winter months.","vi":"Rau tươi khan hiếm trong những tháng mùa đông."}]', '[{"phrase":"supply of"},{"phrase":"office supplies"},{"phrase":"in short supply"},{"phrase":"water supply"}]', 'supply (v) = cung cấp: supply somebody with something', '/səˈplaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supply__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 21, 'village', 'làng', 'noun', '[{"en":"My grandmother still lives in a small village near the mountains.","vi":"Bà tôi vẫn sống ở một ngôi làng nhỏ gần núi."},{"en":"The whole village came to their wedding.","vi":"Cả làng đã đến dự đám cưới của họ."},{"en":"We stayed in a fishing village during our summer trip.","vi":"Chúng tôi ở lại một làng chài trong chuyến đi mùa hè."}]', '[{"phrase":"small village"},{"phrase":"fishing village"},{"phrase":"the whole village"},{"phrase":"village school"}]', NULL, '/ˈvɪlɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vil/villa/village__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 22, 'worth', 'đáng giá; đáng (làm gì)', 'adjective', '[{"en":"This old painting is worth thousands of dollars.","vi":"Bức tranh cũ này trị giá hàng nghìn đô la."},{"en":"The museum is definitely worth a visit if you have time.","vi":"Nếu có thời gian, bảo tàng đó chắc chắn đáng để ghé thăm."},{"en":"It was a long drive, but the view was worth it.","vi":"Lái xe đường dài thật, nhưng cảnh đẹp rất đáng công."}]', '[{"phrase":"worth it"},{"phrase":"worth a visit"},{"phrase":"well worth"}]', 'be worth + V-ing: This book is worth reading.', '/wɜːrθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/worth/worth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 23, 'natural', 'tự nhiên; thiên nhiên', 'adjective', '[{"en":"This shampoo is made from natural ingredients.","vi":"Loại dầu gội này được làm từ các thành phần tự nhiên."},{"en":"It''s natural to feel nervous before a job interview.","vi":"Cảm thấy hồi hộp trước buổi phỏng vấn xin việc là điều tự nhiên."},{"en":"The island is famous for its natural beauty.","vi":"Hòn đảo nổi tiếng với vẻ đẹp thiên nhiên."}]', '[{"phrase":"natural beauty"},{"phrase":"natural ingredients"},{"phrase":"natural resources"},{"phrase":"perfectly natural"}]', NULL, '/ˈnætʃrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natur/natural__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 24, 'express', 'bày tỏ; diễn đạt; thể hiện', 'verb', '[{"en":"He finds it hard to express his feelings.","vi":"Anh ấy thấy khó bày tỏ cảm xúc của mình."},{"en":"I''m not sure how to express this idea in English.","vi":"Tôi không chắc phải diễn đạt ý này bằng tiếng Anh như thế nào."},{"en":"Young children often express themselves through drawing and play.","vi":"Trẻ nhỏ thường thể hiện bản thân qua việc vẽ và vui chơi."}]', '[{"phrase":"express feelings"},{"phrase":"express yourself"},{"phrase":"express an opinion"},{"phrase":"express concern"}]', NULL, '/ɪkˈspres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expre/express__us_6.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 25, 'indicate', 'cho thấy; chỉ ra; báo hiệu', 'verb', '[{"en":"Recent studies indicate that most people don''t get enough sleep.","vi":"Các nghiên cứu gần đây cho thấy hầu hết mọi người không ngủ đủ giấc."},{"en":"She indicated the exit with a wave of her hand.","vi":"Cô ấy vẫy tay chỉ về phía lối ra."},{"en":"The red light indicates that the battery is low.","vi":"Đèn đỏ báo hiệu pin sắp hết."}]', '[{"phrase":"studies indicate"},{"phrase":"results indicate"},{"phrase":"clearly indicate"}]', NULL, '/ˈɪndɪkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indic/indicate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 26, 'attend', 'tham dự; theo học', 'verb', '[{"en":"Over two hundred guests attended the wedding.","vi":"Hơn hai trăm khách đã tham dự đám cưới."},{"en":"All employees must attend the safety meeting on Friday.","vi":"Tất cả nhân viên phải tham dự cuộc họp về an toàn vào thứ Sáu."},{"en":"Both of my kids attend the same elementary school.","vi":"Cả hai con tôi đều học cùng một trường tiểu học."}]', '[{"phrase":"attend a meeting"},{"phrase":"attend school"},{"phrase":"attend a conference"},{"phrase":"regularly attend"}]', 'attend + sự kiện/nơi chốn (không có "to"): attend a meeting', '/əˈtend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/atten/attend__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 27, 'brother', 'anh trai; em trai', 'noun', '[{"en":"My older brother taught me how to ride a bike.","vi":"Anh trai tôi đã dạy tôi đi xe đạp."},{"en":"Do you have any brothers or sisters?","vi":"Bạn có anh chị em nào không?"},{"en":"Her little brother is starting school next month.","vi":"Em trai cô ấy sẽ bắt đầu đi học vào tháng tới."}]', '[{"phrase":"older brother"},{"phrase":"younger brother"},{"phrase":"little brother"},{"phrase":"brothers and sisters"}]', 'anh trai = older brother; em trai = younger/little brother', '/ˈbrʌðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/broth/brother__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 28, 'investment', 'sự đầu tư; khoản đầu tư', 'noun', '[{"en":"Buying a house can be a good long-term investment.","vi":"Mua nhà có thể là một khoản đầu tư dài hạn tốt."},{"en":"The town needs more investment in schools and roads.","vi":"Thị trấn cần được đầu tư nhiều hơn vào trường học và đường sá."},{"en":"Learning a second language is an investment in your future.","vi":"Học thêm một ngoại ngữ là sự đầu tư cho tương lai của bạn."}]', '[{"phrase":"good investment"},{"phrase":"long-term investment"},{"phrase":"investment in"},{"phrase":"foreign investment"}]', NULL, '/ɪnˈvestmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-11', 29, 'score', 'tỷ số; điểm số', 'noun', '[{"en":"What was the final score of the game last night?","vi":"Tỷ số chung cuộc của trận đấu tối qua là bao nhiêu?"},{"en":"She got a perfect score on her math test.","vi":"Cô ấy đạt điểm tuyệt đối trong bài kiểm tra toán."},{"en":"You need a high score to get into that university.","vi":"Bạn cần điểm cao để vào được trường đại học đó."}]', '[{"phrase":"final score"},{"phrase":"high score"},{"phrase":"perfect score"},{"phrase":"test score"}]', NULL, '/skɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sco/score/score__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-12', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 12', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 12);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 1, 'organize', 'tổ chức; sắp xếp', 'verb', '[{"en":"Our class is organizing a trip to the museum next month.","vi":"Lớp chúng tôi đang tổ chức một chuyến đi tham quan bảo tàng vào tháng tới."},{"en":"She spent Sunday afternoon organizing her books and papers.","vi":"Cô ấy dành buổi chiều Chủ nhật để sắp xếp sách vở và giấy tờ."},{"en":"Who organized the party for Dad''s birthday?","vi":"Ai đã tổ chức bữa tiệc sinh nhật cho bố vậy?"}]', '[{"phrase":"organize a trip"},{"phrase":"organize a party"},{"phrase":"organize an event"}]', 'Anh: organise · Mỹ: organize', '/ˈɔːrɡənaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/org/organ/organize__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 2, 'trip', 'chuyến đi', 'noun', '[{"en":"We''re planning a trip to the mountains this summer.","vi":"Chúng tôi đang lên kế hoạch cho một chuyến đi lên núi vào mùa hè này."},{"en":"How was your business trip to Singapore last week?","vi":"Chuyến công tác Singapore tuần trước của bạn thế nào?"},{"en":"The kids were tired after the long trip home.","vi":"Bọn trẻ mệt lả sau chuyến đi dài về nhà."}]', '[{"phrase":"business trip"},{"phrase":"school trip"},{"phrase":"day trip"},{"phrase":"take a trip"}]', NULL, '/trɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trip_/trip__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 3, 'beyond', 'vượt quá; ngoài; ở bên kia', 'preposition', '[{"en":"The price of that house is beyond what we can afford.","vi":"Giá căn nhà đó vượt quá khả năng chi trả của chúng tôi."},{"en":"We''re sorry, but the delay was beyond our control.","vi":"Chúng tôi xin lỗi, nhưng sự chậm trễ này nằm ngoài tầm kiểm soát của chúng tôi."},{"en":"There is a small village just beyond the river.","vi":"Có một ngôi làng nhỏ ngay bên kia con sông."}]', '[{"phrase":"beyond our control"},{"phrase":"go beyond"},{"phrase":"far beyond"},{"phrase":"beyond doubt"}]', NULL, '/bɪˈjɑːnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bey/beyon/beyond__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 4, 'sleep', 'ngủ; giấc ngủ', 'verb', '[{"en":"I couldn''t sleep last night because of the noise.","vi":"Tối qua tôi không ngủ được vì tiếng ồn."},{"en":"Babies usually sleep for most of the day.","vi":"Trẻ sơ sinh thường ngủ gần như cả ngày."},{"en":"You need a good night''s sleep before the exam.","vi":"Bạn cần ngủ một giấc thật ngon trước kỳ thi."}]', '[{"phrase":"go to sleep"},{"phrase":"sleep well"},{"phrase":"get some sleep"}]', 'sleep – slept – slept', '/sliːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sle/sleep/sleep__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 5, 'fish', 'cá', 'noun', '[{"en":"We had grilled fish and rice for dinner.","vi":"Bữa tối chúng tôi ăn cá nướng với cơm."},{"en":"My brother caught three small fish in the lake.","vi":"Anh trai tôi bắt được ba con cá nhỏ ở hồ."},{"en":"How many fish do you keep in that tank?","vi":"Bạn nuôi bao nhiêu con cá trong bể đó?"}]', '[{"phrase":"catch fish"},{"phrase":"fresh fish"},{"phrase":"fish market"},{"phrase":"fried fish"}]', 'Số nhiều thường vẫn là fish', '/fɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fis/fish_/fish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 6, 'promise', 'hứa; lời hứa', 'verb', '[{"en":"I promise I''ll call you as soon as I arrive.","vi":"Tôi hứa sẽ gọi cho bạn ngay khi tôi đến nơi."},{"en":"He promised his mother he would study harder.","vi":"Cậu ấy đã hứa với mẹ là sẽ học chăm hơn."},{"en":"She always keeps her promises, so you can trust her.","vi":"Cô ấy luôn giữ lời hứa, nên bạn có thể tin cô ấy."}]', '[{"phrase":"keep a promise"},{"phrase":"break a promise"},{"phrase":"make a promise"}]', NULL, '/ˈprɑːmɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promi/promise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 7, 'potential', 'tiềm năng; có thể xảy ra', 'adjective', '[{"en":"The company is looking for potential customers in Asia.","vi":"Công ty đang tìm kiếm khách hàng tiềm năng ở châu Á."},{"en":"We need to think about potential problems before we start.","vi":"Chúng ta cần nghĩ đến những vấn đề có thể xảy ra trước khi bắt đầu."},{"en":"She sees him as a potential leader of the team.","vi":"Cô ấy xem anh ấy là một trưởng nhóm tiềm năng."}]', '[{"phrase":"potential customers"},{"phrase":"potential problems"},{"phrase":"potential risks"},{"phrase":"potential benefits"}]', 'Cũng là danh từ: tiềm năng (reach your potential)', '/pəˈtenʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/poten/potential__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 8, 'energy', 'năng lượng; sức lực', 'noun', '[{"en":"I don''t have the energy to cook tonight.","vi":"Tối nay tôi không còn sức để nấu ăn."},{"en":"Solar panels help us save energy and money.","vi":"Tấm pin mặt trời giúp chúng ta tiết kiệm năng lượng và tiền bạc."},{"en":"Kids seem to have so much energy in the morning.","vi":"Bọn trẻ dường như tràn đầy năng lượng vào buổi sáng."}]', '[{"phrase":"save energy"},{"phrase":"solar energy"},{"phrase":"full of energy"},{"phrase":"energy costs"}]', 'Thường không đếm được', '/ˈenərdʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ene/energ/energy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 9, 'trouble', 'rắc rối; khó khăn; sự phiền hà', 'noun', '[{"en":"I had trouble finding your house in the dark.","vi":"Tôi gặp khó khăn khi tìm nhà bạn trong bóng tối."},{"en":"He got into trouble for being late again.","vi":"Cậu ấy lại gặp rắc rối vì đi muộn."},{"en":"Thanks for your help, and sorry for all the trouble.","vi":"Cảm ơn bạn đã giúp, và xin lỗi vì đã làm phiền bạn nhiều."}]', '[{"phrase":"have trouble"},{"phrase":"get into trouble"},{"phrase":"in trouble"}]', 'have trouble + V-ing', '/ˈtrʌbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tro/troub/trouble__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 10, 'relation', 'mối quan hệ; sự liên quan', 'noun', '[{"en":"The company has good relations with its customers.","vi":"Công ty có mối quan hệ tốt với khách hàng."},{"en":"This question has no relation to today''s topic.","vi":"Câu hỏi này không liên quan gì đến chủ đề hôm nay."},{"en":"In relation to your request, we will reply next week.","vi":"Liên quan đến yêu cầu của bạn, chúng tôi sẽ trả lời vào tuần sau."}]', '[{"phrase":"in relation to"},{"phrase":"good relations"},{"phrase":"public relations"}]', NULL, '/rɪˈleɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relation__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 11, 'touch', 'chạm; sờ; làm cảm động', 'verb', '[{"en":"Please don''t touch the paintings in the gallery.","vi":"Vui lòng không chạm vào các bức tranh trong phòng trưng bày."},{"en":"The baby reached out and touched my face.","vi":"Em bé với tay ra và sờ lên mặt tôi."},{"en":"We were deeply touched by their kind words.","vi":"Chúng tôi rất cảm động trước những lời tử tế của họ."}]', '[{"phrase":"touch the screen"},{"phrase":"deeply touched"},{"phrase":"keep in touch"},{"phrase":"get in touch"}]', NULL, '/tʌtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/touch/touch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 12, 'file', 'tập tin; hồ sơ', 'noun', '[{"en":"Can you send me the file by email?","vi":"Bạn gửi cho tôi tập tin đó qua email được không?"},{"en":"I accidentally deleted an important file from my laptop.","vi":"Tôi lỡ tay xóa một tập tin quan trọng khỏi máy tính xách tay."},{"en":"The doctor checked my file before asking any questions.","vi":"Bác sĩ xem hồ sơ của tôi trước khi hỏi bất cứ điều gì."}]', '[{"phrase":"open a file"},{"phrase":"save a file"},{"phrase":"delete a file"},{"phrase":"send a file"}]', NULL, '/faɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/file_/file__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 13, 'middle', 'giữa; phần giữa', 'noun', '[{"en":"There''s a big table in the middle of the room.","vi":"Có một cái bàn lớn ở giữa phòng."},{"en":"My phone rang in the middle of the meeting.","vi":"Điện thoại của tôi đổ chuông giữa cuộc họp."},{"en":"He often wakes up in the middle of the night.","vi":"Anh ấy thường thức giấc giữa đêm."}]', '[{"phrase":"in the middle of"},{"phrase":"middle of the night"},{"phrase":"right in the middle"}]', NULL, '/ˈmɪdl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mid/middl/middle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 14, 'bar', 'quán bar; thanh; thỏi', 'noun', '[{"en":"Let''s meet at the bar near the station after work.","vi":"Tan làm mình gặp nhau ở quán bar gần nhà ga nhé."},{"en":"She ate a chocolate bar on the way to school.","vi":"Cô ấy ăn một thanh sô-cô-la trên đường đến trường."},{"en":"The windows on the ground floor have metal bars.","vi":"Các cửa sổ ở tầng trệt có thanh sắt chắn."}]', '[{"phrase":"chocolate bar"},{"phrase":"a bar of soap"},{"phrase":"go to a bar"}]', NULL, '/bɑːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bar/bar__/bar__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 15, 'suffer', 'chịu đựng; bị (bệnh, đau); bị ảnh hưởng xấu', 'verb', '[{"en":"My grandfather suffers from back pain in winter.","vi":"Ông tôi bị đau lưng vào mùa đông."},{"en":"Many farmers suffered during the long, dry summer.","vi":"Nhiều nông dân đã chịu khổ trong suốt mùa hè khô hạn kéo dài."},{"en":"Her grades suffered because she worked too many hours.","vi":"Điểm số của cô ấy bị sa sút vì cô ấy đi làm quá nhiều giờ."}]', '[{"phrase":"suffer from"},{"phrase":"suffer pain"},{"phrase":"suffer a loss"},{"phrase":"suffer damage"}]', 'suffer from + bệnh/vấn đề', '/ˈsʌfər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suf/suffe/suffer__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 16, 'strategy', 'chiến lược', 'noun', '[{"en":"Our team needs a new strategy to win more customers.","vi":"Nhóm chúng ta cần một chiến lược mới để thu hút thêm khách hàng."},{"en":"What''s your strategy for learning new words?","vi":"Chiến lược học từ mới của bạn là gì?"},{"en":"The company changed its marketing strategy last year.","vi":"Năm ngoái công ty đã thay đổi chiến lược tiếp thị."}]', '[{"phrase":"develop a strategy"},{"phrase":"marketing strategy"},{"phrase":"business strategy"},{"phrase":"strategy for"}]', NULL, '/ˈstrætədʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strat/strategy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 17, 'deep', 'sâu; (giấc ngủ) say', 'adjective', '[{"en":"Be careful, because the water is very deep here.","vi":"Cẩn thận nhé, vì nước ở đây rất sâu."},{"en":"She took a deep breath and opened the door.","vi":"Cô ấy hít một hơi thật sâu rồi mở cửa."},{"en":"The baby fell into a deep sleep after lunch.","vi":"Em bé ngủ say sau bữa trưa."}]', '[{"phrase":"deep water"},{"phrase":"deep breath"},{"phrase":"deep sleep"}]', NULL, '/diːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dee/deep_/deep__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 18, 'except', 'ngoại trừ; trừ', 'preposition', '[{"en":"The shop is open every day except Sunday.","vi":"Cửa hàng mở cửa mọi ngày trừ Chủ nhật."},{"en":"Everyone came to the party except my brother.","vi":"Mọi người đều đến dự tiệc ngoại trừ anh trai tôi."},{"en":"I''ve finished all my homework except the math questions.","vi":"Tôi đã làm xong hết bài tập về nhà trừ mấy câu toán."}]', '[{"phrase":"except for"},{"phrase":"except that"},{"phrase":"every day except"}]', NULL, '/ɪkˈsept/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excep/except__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 19, 'clean', 'sạch; sạch sẽ', 'adjective', '[{"en":"Put on a clean shirt before we go out.","vi":"Mặc áo sơ mi sạch vào trước khi chúng ta ra ngoài nhé."},{"en":"The hotel room was clean and quiet.","vi":"Phòng khách sạn sạch sẽ và yên tĩnh."},{"en":"Is this water clean enough to drink?","vi":"Nước này có đủ sạch để uống không?"}]', '[{"phrase":"clean water"},{"phrase":"clean clothes"},{"phrase":"keep clean"},{"phrase":"clean air"}]', 'Cũng là động từ: làm sạch, dọn dẹp (clean the room)', '/kliːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cle/clean/clean__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 20, 'tend', 'có xu hướng; thường hay', 'verb', '[{"en":"I tend to eat more when I''m stressed.","vi":"Tôi thường hay ăn nhiều hơn khi bị căng thẳng."},{"en":"Prices tend to rise before the holidays.","vi":"Giá cả có xu hướng tăng trước các kỳ nghỉ lễ."},{"en":"Older people tend to go to bed earlier.","vi":"Người lớn tuổi thường có xu hướng đi ngủ sớm hơn."}]', '[{"phrase":"tend to do"},{"phrase":"tend to be"},{"phrase":"tend to agree"}]', 'tend to + động từ nguyên mẫu', '/tend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tend_/tend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 21, 'advance', 'sự tiến bộ; trước (in advance)', 'noun', '[{"en":"Please book your tickets at least two weeks in advance.","vi":"Vui lòng đặt vé trước ít nhất hai tuần."},{"en":"Recent advances in medicine have helped people live longer.","vi":"Những tiến bộ gần đây trong y học đã giúp con người sống lâu hơn."},{"en":"Thanks in advance for your help with this project.","vi":"Cảm ơn trước vì bạn đã giúp đỡ trong dự án này."}]', '[{"phrase":"in advance"},{"phrase":"thanks in advance"},{"phrase":"advances in technology"}]', NULL, '/ədˈvæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advan/advance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 22, 'fill', 'làm đầy; đổ đầy; điền', 'verb', '[{"en":"Can you fill this bottle with cold water?","vi":"Bạn đổ đầy nước lạnh vào chai này giúp mình được không?"},{"en":"Please fill in the form and sign at the bottom.","vi":"Vui lòng điền vào mẫu đơn và ký tên ở phía dưới."},{"en":"The room filled with laughter when the kids arrived.","vi":"Căn phòng tràn ngập tiếng cười khi bọn trẻ đến."}]', '[{"phrase":"fill in a form"},{"phrase":"fill a glass"},{"phrase":"fill with"},{"phrase":"fill up"}]', NULL, '/fɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/fill_/fill__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 23, 'star', 'ngôi sao; sao (xếp hạng)', 'noun', '[{"en":"We lay on the grass and looked at the stars.","vi":"Chúng tôi nằm trên cỏ và ngắm sao."},{"en":"She became a movie star at the age of twenty.","vi":"Cô ấy trở thành ngôi sao điện ảnh năm hai mươi tuổi."},{"en":"The hotel has four stars and a lovely pool.","vi":"Khách sạn này đạt bốn sao và có một hồ bơi rất đẹp."}]', '[{"phrase":"movie star"},{"phrase":"bright star"},{"phrase":"pop star"},{"phrase":"five-star hotel"}]', NULL, '/stɑːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/star_/star__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 24, 'network', 'mạng lưới; mạng (máy tính)', 'noun', '[{"en":"The city has a good network of bus routes.","vi":"Thành phố có mạng lưới tuyến xe buýt tốt."},{"en":"I can''t connect to the office network from home.","vi":"Tôi không kết nối được với mạng của văn phòng khi ở nhà."},{"en":"A strong network of contacts can help you find a job.","vi":"Một mạng lưới quan hệ vững chắc có thể giúp bạn tìm được việc làm."}]', '[{"phrase":"social network"},{"phrase":"computer network"},{"phrase":"road network"},{"phrase":"network of"}]', NULL, '/ˈnetwɜːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/net/netwo/network__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 25, 'generally', 'nói chung; thường', 'adverb', '[{"en":"I generally go to bed before eleven.","vi":"Tôi thường đi ngủ trước mười một giờ."},{"en":"The weather here is generally warm in spring.","vi":"Thời tiết ở đây vào mùa xuân nhìn chung là ấm áp."},{"en":"Generally speaking, kids learn languages faster than adults.","vi":"Nói chung, trẻ em học ngoại ngữ nhanh hơn người lớn."}]', '[{"phrase":"generally speaking"},{"phrase":"generally accepted"},{"phrase":"generally agree"}]', NULL, '/ˈdʒenrəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generally__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 26, 'operation', 'ca phẫu thuật; hoạt động; sự vận hành', 'noun', '[{"en":"My father had an operation on his knee last month.","vi":"Tháng trước bố tôi đã phẫu thuật đầu gối."},{"en":"The new factory will be in operation by next year.","vi":"Nhà máy mới sẽ đi vào hoạt động chậm nhất là vào năm sau."},{"en":"The company''s operations in Asia are growing quickly.","vi":"Hoạt động của công ty ở châu Á đang phát triển nhanh chóng."}]', '[{"phrase":"have an operation"},{"phrase":"in operation"},{"phrase":"business operations"}]', NULL, '/ˌɑːpəˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/operation__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 27, 'match', 'trận đấu; que diêm', 'noun', '[{"en":"Did you watch the football match last night?","vi":"Tối qua bạn có xem trận bóng đá không?"},{"en":"Our team lost the match by just one point.","vi":"Đội chúng tôi thua trận chỉ cách biệt một điểm."},{"en":"He lit the candle with a match.","vi":"Anh ấy châm nến bằng một que diêm."}]', '[{"phrase":"football match"},{"phrase":"win a match"},{"phrase":"lose a match"},{"phrase":"box of matches"}]', 'Động từ: hợp, khớp (Your shoes match your bag.)', '/mætʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/match/match__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 28, 'avoid', 'tránh; né tránh', 'verb', '[{"en":"Try to avoid eating too much sugar.","vi":"Cố gắng tránh ăn quá nhiều đường."},{"en":"We left early to avoid the traffic.","vi":"Chúng tôi đi sớm để tránh kẹt xe."},{"en":"She''s been avoiding me since our argument last week.","vi":"Cô ấy cứ né tránh tôi kể từ lần cãi nhau tuần trước."}]', '[{"phrase":"avoid traffic"},{"phrase":"avoid mistakes"},{"phrase":"avoid problems"}]', 'avoid + V-ing', '/əˈvɔɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/avo/avoid/avoid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-12', 29, 'seat', 'chỗ ngồi; ghế', 'noun', '[{"en":"Is this seat free, or is someone sitting here?","vi":"Chỗ này còn trống không, hay đã có người ngồi rồi?"},{"en":"Please take a seat, and the doctor will see you soon.","vi":"Mời bạn ngồi, bác sĩ sẽ khám cho bạn ngay."},{"en":"I always ask for a window seat on long flights.","vi":"Tôi luôn xin ghế cạnh cửa sổ trên những chuyến bay dài."}]', '[{"phrase":"take a seat"},{"phrase":"window seat"},{"phrase":"front seat"},{"phrase":"book a seat"}]', NULL, '/siːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/seat_/seat__us_1.mp3', NULL, NULL);
